import numpy as np


def construct(budget_seconds, start):
    """Code Zero: keep the start if there is one, otherwise 32 small equal circles on a grid."""
    if start is not None:
        return np.asarray(start, dtype=float)
    k = int(np.ceil(np.sqrt(32)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:32]
    return np.array([[x, y, 0.02] for x, y in pts])

import numpy as np


def construct(budget_seconds, start):
    if start is not None:
        start = np.asarray(start, dtype=float)
        if start.shape == (32, 3) and np.sum(start[:, 2]) >= 2.2:
            return start

    r = 1.0 / 14.0 - 1e-9
    pts = []
    for j in range(7):
        for i in range(5):
            pts.append(((i + 0.5) / 5.0, (j + 0.5) / 7.0))
    pts = pts[:32]
    return np.array([[x, y, r] for x, y in pts], dtype=float)

import numpy as np
import time
from scipy.optimize import minimize, linprog, least_squares
from scipy.spatial import cKDTree


N = 32


def _unpack(z, n=N):
    z = z.reshape(n, 3)
    return z[:, 0].copy(), z[:, 1].copy(), z[:, 2].copy()


def _neg_sum(z):
    return -np.sum(z.reshape(-1, 3)[:, 2])


def _neg_sum_grad(z):
    g = np.zeros_like(z)
    g.reshape(-1, 3)[:, 2] = -1.0
    return g


def _constraints(n):
    ii, jj = np.triu_indices(n, 1)

    def wall(z):
        x, y, r = _unpack(z, n)
        return np.concatenate([x - r, 1.0 - x - r, y - r, 1.0 - y - r])

    def wall_grad(z):
        g = np.zeros((4 * n, 3 * n))
        for k in range(n):
            g[k, 3 * k] = 1.0; g[k, 3 * k + 2] = -1.0
            g[n + k, 3 * k] = -1.0; g[n + k, 3 * k + 2] = -1.0
            g[2 * n + k, 3 * k + 1] = 1.0; g[2 * n + k, 3 * k + 2] = -1.0
            g[3 * n + k, 3 * k + 1] = -1.0; g[3 * n + k, 3 * k + 2] = -1.0
        return g

    def overlap(z):
        x, y, r = _unpack(z, n)
        dx = x[ii] - x[jj]; dy = y[ii] - y[jj]
        return dx * dx + dy * dy - (r[ii] + r[jj]) ** 2

    def overlap_grad(z):
        x, y, r = _unpack(z, n)
        m = len(ii)
        g = np.zeros((m, 3 * n))
        dx = x[ii] - x[jj]; dy = y[ii] - y[jj]; rs = r[ii] + r[jj]
        cols = np.arange(m)
        g[cols, 3 * ii] = 2 * dx
        g[cols, 3 * jj] = -2 * dx
        g[cols, 3 * ii + 1] = 2 * dy
        g[cols, 3 * jj + 1] = -2 * dy
        g[cols, 3 * ii + 2] = -2 * rs
        g[cols, 3 * jj + 2] = -2 * rs
        return g

    return [{'type': 'ineq', 'fun': wall, 'jac': wall_grad},
            {'type': 'ineq', 'fun': overlap, 'jac': overlap_grad}]


def _repair(z, n=N):
    z = z.reshape(n, 3).copy()
    x, y, r = z[:, 0], z[:, 1], z[:, 2]
    r = np.maximum(r, 1e-6)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    for _ in range(300):
        tree = cKDTree(np.column_stack([x, y]))
        pairs = tree.query_pairs(r=0.5, output_type='ndarray')
        if len(pairs) == 0:
            break
        changed = False
        for i, j in pairs:
            d = np.hypot(x[i] - x[j], y[i] - y[j])
            s = r[i] + r[j]
            if d < s - 1e-15:
                if d < 1e-12:
                    r[i] *= 0.5; r[j] *= 0.5
                else:
                    f = (d / s) * (1.0 - 1e-12)
                    r[i] *= f; r[j] *= f
                changed = True
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
        if not changed:
            break
    z[:, 0], z[:, 1], z[:, 2] = x, y, r
    return z.reshape(-1)


def _initial(n=N, seed=7):
    rng = np.random.default_rng(seed)
    pts = []
    for j in range(7):
        for i in range(5):
            pts.append(((i + 0.5) / 5.0, (j + 0.5) / 7.0))
    pts = pts[:n]
    r0 = 1.0 / 14.0 - 1e-6
    return np.array([[x, y, r0] for x, y in pts], dtype=float).reshape(-1)


def _lp_solve(centers, n=N):
    x = centers[:, 0]; y = centers[:, 1]
    ii, jj = np.triu_indices(n, 1)
    dx = x[ii] - x[jj]; dy = y[ii] - y[jj]
    d = np.maximum(np.hypot(dx, dy), 1e-12)

    m = 4 * n + len(ii)
    A_ub = np.zeros((m, n))
    b_ub = np.zeros(m)
    k = 0
    for i in range(n):
        for val in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
            A_ub[k, i] = 1.0
            b_ub[k] = max(val, 0.0)
            k += 1
    for t in range(len(ii)):
        A_ub[k, ii[t]] = 1.0
        A_ub[k, jj[t]] = 1.0
        b_ub[k] = d[t]
        k += 1
    c = -np.ones(n)
    try:
        res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=(0, None), method='highs')
        if not res.success:
            return None, -np.inf, None, ii, jj, d
        marg = None
        try:
            marg = res.ineqlin.marginals
        except Exception:
            pass
        return res.x, -res.fun, (marg, A_ub, b_ub), ii, jj, d
    except Exception:
        return None, -np.inf, None, ii, jj, d


def _lp_grad(centers, n, info, ii, jj, d):
    marg, A_ub, b_ub = info
    if marg is None:
        return None
    x = centers[:, 0]; y = centers[:, 1]
    g = np.zeros((n, 2))
    lam = -np.asarray(marg)
    idx = 0
    for i in range(n):
        g[i, 0] += lam[idx]; idx += 1
        g[i, 0] -= lam[idx]; idx += 1
        g[i, 1] += lam[idx]; idx += 1
        g[i, 1] -= lam[idx]; idx += 1
    for t in range(len(ii)):
        lk = lam[idx]; idx += 1
        a, b = ii[t], jj[t]
        ddx = (x[a] - x[b]) / d[t]
        ddy = (y[a] - y[b]) / d[t]
        g[a, 0] += lk * ddx; g[b, 0] -= lk * ddx
        g[a, 1] += lk * ddy; g[b, 1] -= lk * ddy
    return g


def _active_residual(z, n, pair_list, wall_list):
    x, y, r = _unpack(z, n)
    res = []
    for (i, j) in pair_list:
        res.append(np.hypot(x[i] - x[j], y[i] - y[j]) - (r[i] + r[j]))
    for (i, side) in wall_list:
        if side == 0: res.append(x[i] - r[i])
        elif side == 1: res.append(1.0 - x[i] - r[i])
        elif side == 2: res.append(y[i] - r[i])
        else: res.append(1.0 - y[i] - r[i])
    return np.array(res)


def _active_jacobian(z, n, pair_list, wall_list):
    x, y, r = _unpack(z, n)
    m = len(pair_list) + len(wall_list)
    A = np.zeros((m, 3 * n))
    k = 0
    for (i, j) in pair_list:
        dx = x[i] - x[j]; dy = y[i] - y[j]
        d = max(np.hypot(dx, dy), 1e-14)
        ux = dx / d; uy = dy / d
        A[k, 3 * i] = ux; A[k, 3 * j] = -ux
        A[k, 3 * i + 1] = uy; A[k, 3 * j + 1] = -uy
        A[k, 3 * i + 2] = -1.0; A[k, 3 * j + 2] = -1.0
        k += 1
    for (i, side) in wall_list:
        if side == 0: A[k, 3 * i] = 1.0; A[k, 3 * i + 2] = -1.0
        elif side == 1: A[k, 3 * i] = -1.0; A[k, 3 * i + 2] = -1.0
        elif side == 2: A[k, 3 * i + 1] = 1.0; A[k, 3 * i + 2] = -1.0
        else: A[k, 3 * i + 1] = -1.0; A[k, 3 * i + 2] = -1.0
        k += 1
    return A


def _identify_active(z, n, tol=1e-5):
    x, y, r = _unpack(z, n)
    pair_list = []
    for i in range(n):
        for j in range(i + 1, n):
            if np.hypot(x[i] - x[j], y[i] - y[j]) - (r[i] + r[j]) < tol:
                pair_list.append((i, j))
    wall_list = []
    for i in range(n):
        if x[i] - r[i] < tol: wall_list.append((i, 0))
        if 1.0 - x[i] - r[i] < tol: wall_list.append((i, 1))
        if y[i] - r[i] < tol: wall_list.append((i, 2))
        if 1.0 - y[i] - r[i] < tol: wall_list.append((i, 3))
    return pair_list, wall_list


def _sqp_active(z, n, iters=60, tol=1e-6):
    """KKT Newton on the active contact manifold."""
    z = z.reshape(n, 3).copy()
    g = np.zeros(3 * n)
    g.reshape(n, 3)[:, 2] = -1.0

    def c_and_A(zz):
        pl, wl = _identify_active(zz.reshape(-1), n, tol=tol)
        if len(pl) + len(wl) == 0:
            return np.zeros(0), np.zeros((0, 3 * n))
        return _active_residual(zz.reshape(-1), n, pl, wl), _active_jacobian(zz.reshape(-1), n, pl, wl)

    c, A = c_and_A(z)
    m = len(c)
    if m == 0:
        return z.reshape(-1)
    lam = np.zeros(m)

    for _ in range(iters):
        K = np.zeros((3 * n + m, 3 * n + m))
        K[:3 * n, 3 * n:] = A.T
        K[3 * n:, :3 * n] = A
        rhs = np.zeros(3 * n + m)
        rhs[:3 * n] = -(g + A.T @ lam)
        rhs[3 * n:] = -c
        try:
            sol, *_ = np.linalg.lstsq(K, rhs, rcond=None)
        except Exception:
            break
        dz = sol[:3 * n]
        dlam = sol[3 * n:]
        if not np.all(np.isfinite(dz)) or np.linalg.norm(dz) < 1e-15:
            break
        sum_r0 = float(np.sum(z[:, 2]))
        cn0 = np.linalg.norm(c)
        alpha = 1.0
        accepted = False
        best_z = None
        for _ls in range(30):
            zt = z + alpha * dz.reshape(n, 3)
            zt[:, 2] = np.maximum(zt[:, 2], 1e-9)
            ct, At = c_and_A(zt)
            cnt = np.linalg.norm(ct) if len(ct) else 0.0
            sum_rt = float(np.sum(zt[:, 2]))
            if sum_rt >= sum_r0 - 1e-15 and cnt <= cn0 * (1.0 + 1e-12):
                best_z = zt; accepted = True
                break
            alpha *= 0.5
        if not accepted:
            break
        z = best_z
        c, A = c_and_A(z)
        m = len(c)
        if m == 0:
            break
        if len(dlam) == m:
            lam = lam + alpha * dlam
        else:
            lam = np.zeros(m)
    return z.reshape(-1)


def _slack_shrink(z, n=N):
    z = z.reshape(n, 3).copy()
    x, y, r = z[:, 0], z[:, 1], z[:, 2]
    m = np.minimum.reduce([x - r, 1.0 - x - r, y - r, 1.0 - y - r])
    ii, jj = np.triu_indices(n, 1)
    d = np.hypot(x[ii] - x[jj], y[ii] - y[jj])
    s = d - (r[ii] + r[jj])
    np.minimum.at(m, ii, s)
    np.minimum.at(m, jj, s)
    delta = np.maximum(0.0, -m) + 1e-13
    r = np.maximum(r - delta, 1e-12)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    z[:, 0], z[:, 1], z[:, 2] = x, y, r
    return z.reshape(-1)


def _safe_sum(z, n=N):
    return float(np.sum(z.reshape(n, 3)[:, 2]))


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = N

    def time_left():
        return budget_seconds - (time.process_time() - t0)

    if start is not None:
        s = np.asarray(start, dtype=float).reshape(n, 3).copy()
        s[:, 2] = np.maximum(s[:, 2], 1e-6)
        z_start = _repair(s.reshape(-1), n)
    else:
        z_start = _initial(n)

    best_z = z_start.copy()
    best_val = _safe_sum(best_z, n)

    bounds = []
    for _ in range(n):
        bounds.append((0.0, 1.0)); bounds.append((0.0, 1.0)); bounds.append((1e-7, 0.5))
    cons = _constraints(n)

    def run_slsqp(zinit, maxiter, ftol=1e-13):
        try:
            res = minimize(_neg_sum, zinit, jac=_neg_sum_grad,
                           method='SLSQP', bounds=bounds, constraints=cons,
                           options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
            if res.x is not None:
                zc = _slack_shrink(_repair(res.x, n), n)
                return zc, _safe_sum(zc, n)
        except Exception:
            pass
        return None, -np.inf

    # 1) Polish start with SLSQP
    if time_left() > 6.0:
        zc, val = run_slsqp(best_z.copy(), 600)
        if val > best_val:
            best_val, best_z = val, zc

    # 2) LP-driven center optimization from start's centers
    if time_left() > 3.0:
        centers = best_z.reshape(n, 3)[:, :2].copy()
        centers = np.clip(centers, 1e-4, 1.0 - 1e-4)
        r, val, info, ii, jj, d = _lp_solve(centers, n)
        best_centers = centers.copy()
        best_lp = val if r is not None else -np.inf
        lr = 0.003
        lp_end = t0 + 0.55 * budget_seconds
        while time.process_time() < lp_end:
            r, val, info, ii, jj, d = _lp_solve(centers, n)
            if r is None:
                break
            if val > best_lp:
                best_lp = val; best_centers = centers.copy()
            g = _lp_grad(centers, n, info, ii, jj, d)
            if g is None or not np.all(np.isfinite(g)):
                break
            gn = np.linalg.norm(g)
            if gn < 1e-12:
                break
            step = lr
            ok = False
            for _ in range(8):
                newc = centers + step * g
                newc[:, 0] = np.clip(newc[:, 0], r + 1e-6, 1.0 - r - 1e-6)
                newc[:, 1] = np.clip(newc[:, 1], r + 1e-6, 1.0 - r - 1e-6)
                _, vnew, _, _, _, _ = _lp_solve(newc, n)
                if np.isfinite(vnew) and vnew >= val - 1e-12:
                    centers = newc; ok = True
                    if vnew > best_lp:
                        best_lp = vnew; best_centers = newc.copy()
                    break
                step *= 0.5
            if not ok:
                lr *= 0.7
                if lr < 1e-6:
                    break
        r_best, _, _, _, _, _ = _lp_solve(best_centers, n)
        if r_best is not None:
            zcand = np.column_stack([best_centers, np.maximum(r_best - 1e-9, 1e-10)])
            zcand = _repair(zcand.reshape(-1), n)
            if _safe_sum(zcand, n) > best_val:
                best_val = _safe_sum(zcand, n); best_z = zcand

    # 3) SLSQP polish of LP result + KKT Newton
    if time_left() > 2.0:
        zc, val = run_slsqp(best_z.copy(), 600)
        if val > best_val:
            best_val, best_z = val, zc
    if time_left() > 1.5:
        try:
            zsq = _sqp_active(best_z.copy(), n, iters=80, tol=1e-6)
            zsq = _slack_shrink(zsq, n)
            vsq = _safe_sum(zsq, n)
            if vsq > best_val:
                best_val, best_z = vsq, zsq
        except Exception:
            pass

    # 4) Random perturbations if time remains
    rng = np.random.default_rng(2024)
    attempt = 0
    while time_left() > 0.6 and attempt < 20:
        attempt += 1
        scale = [0.003, 0.01, 0.02, 0.04][attempt % 4]
        zp = best_z.reshape(n, 3).copy()
        zp[:, 0] += rng.normal(0, scale, n)
        zp[:, 1] += rng.normal(0, scale, n)
        zp[:, 2] *= (1.0 + rng.normal(0, scale * 1.5, n))
        zp = _repair(zp.reshape(-1), n)
        if _safe_sum(zp, n) < best_val - 0.01:
            continue
        zc, val = run_slsqp(zp, 400)
        if val > best_val:
            best_val, best_z = val, zc
        if time_left() > 0.4:
            try:
                zsq = _sqp_active(best_z.copy(), n, iters=40, tol=1e-6)
                zsq = _slack_shrink(zsq, n)
                vsq = _safe_sum(zsq, n)
                if vsq > best_val:
                    best_val, best_z = vsq, zsq
            except Exception:
                pass

    out = _slack_shrink(best_z, n).reshape(n, 3).copy()
    return out

import numpy as np
import time
from scipy.optimize import minimize, linprog, least_squares
from scipy.spatial import cKDTree


def _pack(z, n):
    z = z.reshape(n, 3)
    return z[:, 0], z[:, 1], z[:, 2]


def _neg_sum(z):
    return -np.sum(z.reshape(-1, 3)[:, 2])


def _neg_sum_grad(z):
    g = np.zeros_like(z)
    g.reshape(-1, 3)[:, 2] = -1.0
    return g


def _constraints(n, pair_list=None, wall_list=None):
    if pair_list is None:
        pair_list = [(i, j) for i in range(n) for j in range(i + 1, n)]
    if wall_list is None:
        wall_list = [(i, s) for i in range(n) for s in range(4)]
    ii = np.array([p[0] for p in pair_list], dtype=int)
    jj = np.array([p[1] for p in pair_list], dtype=int)
    wi = np.array([w[0] for w in wall_list], dtype=int)
    ws = np.array([w[1] for w in wall_list], dtype=int)

    def wall(z):
        x, y, r = _pack(z, n)
        out = np.empty(len(wi))
        for k in range(len(wi)):
            i = wi[k]; s = ws[k]
            if s == 0:
                out[k] = x[i] - r[i]
            elif s == 1:
                out[k] = 1.0 - x[i] - r[i]
            elif s == 2:
                out[k] = y[i] - r[i]
            else:
                out[k] = 1.0 - y[i] - r[i]
        return out

    def wall_grad(z):
        g = np.zeros((len(wi), 3 * n))
        for k in range(len(wi)):
            i = wi[k]; s = ws[k]
            if s == 0:
                g[k, 3 * i] = 1.0; g[k, 3 * i + 2] = -1.0
            elif s == 1:
                g[k, 3 * i] = -1.0; g[k, 3 * i + 2] = -1.0
            elif s == 2:
                g[k, 3 * i + 1] = 1.0; g[k, 3 * i + 2] = -1.0
            else:
                g[k, 3 * i + 1] = -1.0; g[k, 3 * i + 2] = -1.0
        return g

    def overlap(z):
        x, y, r = _pack(z, n)
        dx = x[ii] - x[jj]
        dy = y[ii] - y[jj]
        return dx * dx + dy * dy - (r[ii] + r[jj]) ** 2

    def overlap_grad(z):
        x, y, r = _pack(z, n)
        m = len(ii)
        g = np.zeros((m, 3 * n))
        dx = x[ii] - x[jj]
        dy = y[ii] - y[jj]
        rs = r[ii] + r[jj]
        for k in range(m):
            a, b = ii[k], jj[k]
            g[k, 3 * a] = 2 * dx[k]
            g[k, 3 * b] = -2 * dx[k]
            g[k, 3 * a + 1] = 2 * dy[k]
            g[k, 3 * b + 1] = -2 * dy[k]
            g[k, 3 * a + 2] = -2 * rs[k]
            g[k, 3 * b + 2] = -2 * rs[k]
        return g

    cons = []
    if len(wi) > 0:
        cons.append({'type': 'ineq', 'fun': wall, 'jac': wall_grad})
    if len(ii) > 0:
        cons.append({'type': 'ineq', 'fun': overlap, 'jac': overlap_grad})
    return cons


def _repair(z, n):
    z = z.reshape(n, 3).copy()
    x, y, r = z[:, 0], z[:, 1], z[:, 2]
    r = np.maximum(r, 1e-6)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    for _ in range(300):
        tree = cKDTree(np.column_stack([x, y]))
        pairs = tree.query_pairs(r=0.5, output_type='ndarray')
        if len(pairs) == 0:
            break
        changed = False
        for i, j in pairs:
            d = np.hypot(x[i] - x[j], y[i] - y[j])
            s = r[i] + r[j]
            if d < s - 1e-15:
                if d < 1e-12:
                    r[i] *= 0.5
                    r[j] *= 0.5
                else:
                    f = (d / s) * (1.0 - 1e-12)
                    r[i] *= f
                    r[j] *= f
                changed = True
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
        if not changed:
            break
    z[:, 0], z[:, 1], z[:, 2] = x, y, r
    return z.reshape(-1)


def _initial(n):
    rng = np.random.default_rng(7)
    pts = []
    for j in range(7):
        for i in range(5):
            pts.append(((i + 0.5) / 5.0, (j + 0.5) / 7.0))
    pts = pts[:n]
    r0 = 1.0 / 14.0 - 1e-6
    z = np.array([[x, y, r0] for x, y in pts], dtype=float)
    return z.reshape(-1)


def _lp_solve(centers, n):
    x = centers[:, 0]
    y = centers[:, 1]
    pairs = [(i, j) for i in range(n) for j in range(i + 1, n)]
    ii = np.array([p[0] for p in pairs])
    jj = np.array([p[1] for p in pairs])
    dx = x[ii] - x[jj]
    dy = y[ii] - y[jj]
    d = np.hypot(dx, dy)
    d = np.maximum(d, 1e-12)

    rows = []
    bvec = []
    for i in range(n):
        for val in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
            row = np.zeros(n)
            row[i] = 1.0
            rows.append(row)
            bvec.append(max(val, 0.0))
    for k in range(len(ii)):
        row = np.zeros(n)
        row[ii[k]] = 1.0
        row[jj[k]] = 1.0
        rows.append(row)
        bvec.append(d[k])
    A_ub = np.array(rows)
    b_ub = np.array(bvec)
    c = -np.ones(n)
    try:
        res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=(0, None), method='highs')
        if not res.success:
            return None, -np.inf, None, ii, jj, d
        r = res.x
        val = -res.fun
        marg = None
        try:
            marg = res.ineqlin.marginals
        except Exception:
            marg = None
        return r, val, (marg, A_ub, b_ub), ii, jj, d
    except Exception:
        return None, -np.inf, None, ii, jj, d


def _lp_grad(centers, n, info, ii, jj, d):
    marg, A_ub, b_ub = info
    x = centers[:, 0]
    y = centers[:, 1]
    g = np.zeros((n, 2))
    if marg is None:
        return None
    lam = -np.asarray(marg)
    idx = 0
    for i in range(n):
        g[i, 0] += lam[idx]; idx += 1
        g[i, 0] -= lam[idx]; idx += 1
        g[i, 1] += lam[idx]; idx += 1
        g[i, 1] -= lam[idx]; idx += 1
    for k in range(len(ii)):
        lk = lam[idx]; idx += 1
        a, b = ii[k], jj[k]
        ddx = (x[a] - x[b]) / d[k]
        ddy = (y[a] - y[b]) / d[k]
        g[a, 0] += lk * ddx
        g[b, 0] -= lk * ddx
        g[a, 1] += lk * ddy
        g[b, 1] -= lk * ddy
    return g


def _active_residual(z, n, pair_list, wall_list):
    z = z.reshape(n, 3)
    x, y, r = z[:, 0], z[:, 1], z[:, 2]
    res = []
    for (i, j) in pair_list:
        d = np.hypot(x[i] - x[j], y[i] - y[j])
        res.append(d - (r[i] + r[j]))
    for (i, side) in wall_list:
        if side == 0:
            res.append(x[i] - r[i])
        elif side == 1:
            res.append(1.0 - x[i] - r[i])
        elif side == 2:
            res.append(y[i] - r[i])
        else:
            res.append(1.0 - y[i] - r[i])
    return np.array(res)


def _identify_active(z, n, tol=1e-5):
    z = z.reshape(n, 3)
    x, y, r = z[:, 0], z[:, 1], z[:, 2]
    pair_list = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(x[i] - x[j], y[i] - y[j])
            if d - (r[i] + r[j]) < tol:
                pair_list.append((i, j))
    wall_list = []
    for i in range(n):
        if x[i] - r[i] < tol:
            wall_list.append((i, 0))
        if 1.0 - x[i] - r[i] < tol:
            wall_list.append((i, 1))
        if y[i] - r[i] < tol:
            wall_list.append((i, 2))
        if 1.0 - y[i] - r[i] < tol:
            wall_list.append((i, 3))
    return pair_list, wall_list


def _solve_active(z0, n, pair_list, wall_list):
    if len(pair_list) + len(wall_list) == 0:
        return None
    def F(z):
        return _active_residual(z, n, pair_list, wall_list)
    try:
        res = least_squares(
            F, z0.reshape(-1).copy(), method='lm',
            xtol=1e-15, ftol=1e-15, gtol=1e-15, max_nfev=20000,
        )
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(n, 3)
    except Exception:
        pass
    return None


def _slack_shrink(z, n):
    z = z.reshape(n, 3).copy()
    x, y, r = z[:, 0], z[:, 1], z[:, 2]
    m = np.minimum.reduce([x - r, 1.0 - x - r, y - r, 1.0 - y - r])
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(x[i] - x[j], y[i] - y[j])
            s = d - (r[i] + r[j])
            if s < m[i]:
                m[i] = s
            if s < m[j]:
                m[j] = s
    delta = np.maximum(0.0, -m) + 1e-13
    r = np.maximum(r - delta, 1e-12)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    z[:, 0], z[:, 1], z[:, 2] = x, y, r
    return z.reshape(-1)


def _exact_shrink(z, n):
    """Exact per-constraint minimal shrink: compute each circle's max allowed
    radius given others fixed, then shrink by tiny epsilon."""
    z = z.reshape(n, 3).copy()
    x, y, r = z[:, 0], z[:, 1], z[:, 2]
    # For each circle, compute the max radius allowed given all others fixed
    newr = r.copy()
    for i in range(n):
        cap = min(x[i], 1.0 - x[i], y[i], 1.0 - y[i])
        for j in range(n):
            if j == i:
                continue
            d = np.hypot(x[i] - x[j], y[i] - y[j])
            cap = min(cap, d - r[j])
        newr[i] = min(r[i], max(cap, 1e-12))
    # Also verify pairwise with new radii and shrink if needed
    for _ in range(50):
        ok = True
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(x[i] - x[j], y[i] - y[j])
                s = newr[i] + newr[j]
                if d < s:
                    f = d / s * (1.0 - 1e-14)
                    newr[i] *= f
                    newr[j] *= f
                    ok = False
        if ok:
            break
    newr = np.maximum(newr - 1e-13, 1e-12)
    x = np.clip(x, newr, 1.0 - newr)
    y = np.clip(y, newr, 1.0 - newr)
    z[:, 0], z[:, 1], z[:, 2] = x, y, newr
    return z.reshape(-1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32

    def time_left():
        return budget_seconds - (time.process_time() - t0)

    if start is not None:
        s = np.asarray(start, dtype=float).reshape(n, 3).copy()
        s[:, 2] = np.maximum(s[:, 2], 1e-6)
        z0 = _repair(s.reshape(-1), n)
    else:
        z0 = _initial(n)

    z0 = z0.reshape(n, 3)
    centers = z0[:, :2].copy()
    centers = np.clip(centers, 1e-4, 1.0 - 1e-4)

    best_centers = centers.copy()
    r, val, info, ii, jj, d = _lp_solve(centers, n)
    best_val_lp = val if r is not None else -np.inf

    lr = 0.002
    lp_phase_end = t0 + 0.4 * budget_seconds
    it = 0
    while time.process_time() < lp_phase_end and it < 500:
        it += 1
        r, val, info, ii, jj, d = _lp_solve(centers, n)
        if r is None:
            break
        if val > best_val_lp:
            best_val_lp = val
            best_centers = centers.copy()
        g = _lp_grad(centers, n, info, ii, jj, d)
        if g is None or not np.all(np.isfinite(g)):
            break
        gn = np.linalg.norm(g)
        if gn < 1e-12:
            break
        step = lr
        accepted = False
        for _ in range(8):
            newc = centers + step * g
            rr = r
            newc[:, 0] = np.clip(newc[:, 0], rr + 1e-6, 1.0 - rr - 1e-6)
            newc[:, 1] = np.clip(newc[:, 1], rr + 1e-6, 1.0 - rr - 1e-6)
            _, vnew, _, _, _, _ = _lp_solve(newc, n)
            if np.isfinite(vnew) and vnew >= val - 1e-12:
                centers = newc
                accepted = True
                if vnew > best_val_lp:
                    best_val_lp = vnew
                    best_centers = newc.copy()
                break
            step *= 0.5
        if not accepted:
            lr *= 0.7
            if lr < 1e-6:
                break

    r_best, val_best, _, _, _, _ = _lp_solve(best_centers, n)
    if r_best is not None:
        zstart = np.column_stack([best_centers, np.maximum(r_best - 1e-9, 1e-10)])
        z0 = _repair(zstart.reshape(-1), n)

    z0_orig = _repair(np.asarray(start, dtype=float).reshape(n, 3).reshape(-1), n) if start is not None else z0

    bounds = []
    for _ in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-7, 0.5))

    cons_full = _constraints(n)

    best_z = z0.copy()
    best_val = -_neg_sum(best_z)
    if -_neg_sum(z0_orig) > best_val:
        best_val = -_neg_sum(z0_orig)
        best_z = z0_orig.copy()

    def run_slsqp(zinit, maxiter):
        try:
            res = minimize(
                _neg_sum, zinit, jac=_neg_sum_grad,
                method='SLSQP', bounds=bounds, constraints=cons_full,
                options={'maxiter': maxiter, 'ftol': 1e-13, 'disp': False},
            )
            if res.x is not None:
                zc = _repair(res.x, n)
                return zc, -_neg_sum(zc)
        except Exception:
            pass
        return None, -np.inf

    for cand in (z0, z0_orig):
        zc, val = run_slsqp(cand, 800)
        if val > best_val:
            best_val, best_z = val, zc

    def try_active_polish(zbase):
        zb = zbase.reshape(n, 3).copy()
        pair_list, wall_list = _identify_active(zb, n, tol=1e-5)
        if len(pair_list) + len(wall_list) == 0:
            return None, -np.inf
        zsol = _solve_active(zb, n, pair_list, wall_list)
        if zsol is None:
            return None, -np.inf
        zr = _repair(zsol.reshape(-1), n)
        zs = _slack_shrink(zr, n)
        v = float(np.sum(zs.reshape(n, 3)[:, 2]))
        return zs, v

    zp, vp = try_active_polish(best_z)
    if zp is not None and vp > best_val:
        best_val, best_z = vp, zp

    rng = np.random.default_rng(2024)
    attempt = 0
    while time_left() > 0.8 and attempt < 30:
        attempt += 1
        scale = [0.005, 0.015, 0.03, 0.06][attempt % 4]
        zp = best_z.reshape(n, 3).copy()
        zp[:, 0] += rng.normal(0, scale, n)
        zp[:, 1] += rng.normal(0, scale, n)
        zp[:, 2] *= (1.0 + rng.normal(0, scale * 1.5, n))
        zp = _repair(zp.reshape(-1), n)
        zc, val = run_slsqp(zp, 400)
        if val > best_val:
            best_val, best_z = val, zc

    zp, vp = try_active_polish(best_z)
    if zp is not None and vp > best_val:
        best_val, best_z = vp, zp

    # NEW: trust-constr on active set
    if time_left() > 0.5:
        zb = best_z.reshape(n, 3).copy()
        pair_list, wall_list = _identify_active(zb, n, tol=1e-5)
        if len(pair_list) + len(wall_list) > 0:
            cons_active = _constraints(n, pair_list, wall_list)
            try:
                res_tc = minimize(
                    _neg_sum, best_z.copy(), jac=_neg_sum_grad,
                    method='trust-constr', bounds=bounds,
                    constraints=cons_active,
                    options={'gtol': 1e-14, 'xtol': 1e-16,
                             'barrier_tol': 1e-16, 'maxiter': 2000,
                             'verbose': 0},
                )
                if res_tc.x is not None and np.all(np.isfinite(res_tc.x)):
                    zc = _repair(res_tc.x, n)
                    vc = -_neg_sum(zc)
                    if vc >= best_val - 1e-9:
                        best_z = zc
                        best_val = vc
            except Exception:
                pass

    # Final exact per-constraint minimal shrink
    out = _exact_shrink(best_z, n).reshape(n, 3).copy()
    return out

import numpy as np
import time
import math
from scipy.optimize import linprog
from scipy.spatial import cKDTree


def _lp_radii(centers, n, ii, jj):
    x = centers[:, 0]; y = centers[:, 1]
    dx = x[ii] - x[jj]; dy = y[ii] - y[jj]
    d = np.maximum(np.hypot(dx, dy), 1e-12)
    A_ub = np.zeros((4 * n + len(ii), n))
    b_ub = np.zeros(4 * n + len(ii))
    for i in range(n):
        A_ub[4*i, i] = 1.0;   b_ub[4*i]   = max(x[i], 0.0)
        A_ub[4*i+1, i] = 1.0; b_ub[4*i+1] = max(1.0 - x[i], 0.0)
        A_ub[4*i+2, i] = 1.0; b_ub[4*i+2] = max(y[i], 0.0)
        A_ub[4*i+3, i] = 1.0; b_ub[4*i+3] = max(1.0 - y[i], 0.0)
    for k in range(len(ii)):
        A_ub[4*n+k, ii[k]] = 1.0
        A_ub[4*n+k, jj[k]] = 1.0
        b_ub[4*n+k] = d[k]
    try:
        res = linprog(-np.ones(n), A_ub=A_ub, b_ub=b_ub,
                      bounds=(0, None), method='highs')
        if not res.success:
            return None, -np.inf, None
        return res.x, -res.fun, res
    except Exception:
        return None, -np.inf, None


def _lp_grad(centers, n, ii, jj, res):
    x = centers[:, 0]; y = centers[:, 1]
    dx = x[ii] - x[jj]; dy = y[ii] - y[jj]
    d = np.maximum(np.hypot(dx, dy), 1e-12)
    try:
        lam = -np.asarray(res.ineqlin.marginals)
    except Exception:
        return None
    g = np.zeros((n, 2))
    idx = 0
    for i in range(n):
        g[i, 0] += lam[idx] - lam[idx+1]; idx += 2
        g[i, 1] += lam[idx] - lam[idx+1]; idx += 2
    for k in range(len(ii)):
        lk = lam[idx]; idx += 1
        a, b = ii[k], jj[k]
        ux = (x[a] - x[b]) / d[k]; uy = (y[a] - y[b]) / d[k]
        g[a, 0] += lk * ux; g[b, 0] -= lk * ux
        g[a, 1] += lk * uy; g[b, 1] -= lk * uy
    return g


def _shrink(x, y, r, n):
    r = np.maximum(r.copy(), 1e-11)
    # iteratively fix walls then pairs, several passes
    for _ in range(6):
        for i in range(n):
            for dist in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
                if r[i] > dist:
                    r[i] = math.nextafter(max(dist, 0.0), 0.0)
        r = np.maximum(r, 1e-11)
        for i in range(n):
            for j in range(i + 1, n):
                d = math.hypot(x[i] - x[j], y[i] - y[j])
                s = r[i] + r[j]
                if s > d:
                    excess = s - d
                    r[i] = math.nextafter(r[i] - excess / 2.0, 0.0)
                    r[j] = math.nextafter(r[j] - excess / 2.0, 0.0)
        r = np.maximum(r, 1e-11)
    # final safety: strictly inside
    for i in range(n):
        for dist in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
            if r[i] >= dist:
                r[i] = math.nextafter(max(dist, 0.0), 0.0)
    for i in range(n):
        for j in range(i + 1, n):
            d = math.hypot(x[i] - x[j], y[i] - y[j])
            if r[i] + r[j] >= d:
                r[i] = math.nextafter(r[i], 0.0)
    return np.maximum(r, 1e-11)


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    pairs = [(i, j) for i in range(n) for j in range(i + 1, n)]
    ii = np.array([p[0] for p in pairs])
    jj = np.array([p[1] for p in pairs])

    def time_left():
        return budget_seconds - (time.process_time() - t0)

    if start is not None:
        s = np.asarray(start, dtype=float).reshape(n, 3)
        centers = np.clip(s[:, :2].copy(), 1e-4, 1.0 - 1e-4)
    else:
        pts = []
        for j in range(7):
            for i in range(5):
                pts.append(((i + 0.5) / 5.0, (j + 0.5) / 7.0))
        centers = np.array(pts[:n], dtype=float)

    r0, v0, res0 = _lp_radii(centers, n, ii, jj)
    if r0 is None:
        r0 = np.full(n, 0.05); v0 = float(r0.sum())
    best_centers = centers.copy()
    best_val = v0
    cur_centers = centers.copy()
    cur_val = v0

    rng = np.random.default_rng(987654321)

    # Phase A: stochastic block perturbation with LP objective.
    damp = 0.02
    while time_left() > 0.60 * budget_seconds:
        k = int(rng.integers(1, 6))
        idxs = rng.choice(n, size=k, replace=False)
        trial = cur_centers.copy()
        amp = damp * (0.3 + rng.random())
        trial[idxs] += rng.normal(0, amp, (k, 2))
        trial[:, 0] = np.clip(trial[:, 0], 1e-4, 1.0 - 1e-4)
        trial[:, 1] = np.clip(trial[:, 1], 1e-4, 1.0 - 1e-4)
        rt, vt, _ = _lp_radii(trial, n, ii, jj)
        if rt is None:
            continue
        if vt > cur_val - 1e-13:
            cur_centers = trial; cur_val = vt
            if vt > best_val:
                best_val = vt; best_centers = trial.copy()
        if rng.random() < 0.03:
            damp = max(damp * 0.85, 0.0015)

    # Phase B: gradient ascent using LP marginals.
    cur_centers = best_centers.copy(); cur_val = best_val
    lr = 0.003
    while time_left() > 0.30 * budget_seconds:
        r, v, res = _lp_radii(cur_centers, n, ii, jj)
        if r is None:
            break
        g = _lp_grad(cur_centers, n, ii, jj, res)
        if g is None:
            break
        gn = np.linalg.norm(g)
        if gn < 1e-14:
            break
        accepted = False
        step = lr
        for _ in range(12):
            trial = cur_centers + step * g
            trial[:, 0] = np.clip(trial[:, 0], r + 1e-6, 1.0 - r - 1e-6)
            trial[:, 1] = np.clip(trial[:, 1], r + 1e-6, 1.0 - r - 1e-6)
            rt, vt, _ = _lp_radii(trial, n, ii, jj)
            if rt is not None and np.isfinite(vt) and vt >= v - 1e-13:
                cur_centers = trial; cur_val = vt; accepted = True
                if vt > best_val:
                    best_val = vt; best_centers = trial.copy()
                break
            step *= 0.5
        if not accepted:
            lr *= 0.6
            if lr < 1e-8:
                break

    # Final: LP radii at best, then ULP coordinate ascent.
    x = best_centers[:, 0].copy(); y = best_centers[:, 1].copy()
    r_lp, _, _ = _lp_radii(best_centers, n, ii, jj)
    if r_lp is None:
        r_lp = np.full(n, 0.05)
    r = _shrink(x, y, r_lp, n)
    centers = np.column_stack([x, y]).copy()
    cur_val = float(r.sum())

    # ULP polish: nudge individual coordinates toward increasing objective.
    improved = True
    passes = 0
    while improved and passes < 6 and time_left() > 0.10:
        improved = False
        passes += 1
        for i in range(n):
            if time_left() <= 0.08:
                break
            for k in range(2):
                if time_left() <= 0.08:
                    break
                base = centers[i, k]
                for direction in (math.inf, -math.inf):
                    if time_left() <= 0.08:
                        break
                    cand = math.nextafter(base, direction)
                    if cand < 0.0 or cand > 1.0:
                        continue
                    trial = centers.copy()
                    trial[i, k] = cand
                    rt, vt, _ = _lp_radii(trial, n, ii, jj)
                    if rt is None:
                        continue
                    if vt > cur_val + 1e-14:
                        centers = trial; cur_val = vt; improved = True
                        break
        if passes >= 2:
            break

    # Re-solve LP and shrink strictly for output.
    r_lp, _, _ = _lp_radii(centers, n, ii, jj)
    if r_lp is None:
        r_lp = np.full(n, 0.05)
    r = _shrink(centers[:, 0], centers[:, 1], r_lp, n)
    out = np.column_stack([centers[:, 0], centers[:, 1], r])
    return out

import numpy as np
import time
import math
from scipy.optimize import minimize, linprog, least_squares
from scipy.spatial import cKDTree


def _pack(z, n):
    z = z.reshape(n, 3)
    return z[:, 0], z[:, 1], z[:, 2]


def _neg_sum(z):
    return -np.sum(z.reshape(-1, 3)[:, 2])


def _neg_sum_grad(z):
    g = np.zeros_like(z)
    g.reshape(-1, 3)[:, 2] = -1.0
    return g


def _constraints(n):
    pairs = [(i, j) for i in range(n) for j in range(i + 1, n)]
    ii = np.array([p[0] for p in pairs])
    jj = np.array([p[1] for p in pairs])

    def wall(z):
        x, y, r = _pack(z, n)
        return np.concatenate([x - r, 1.0 - x - r, y - r, 1.0 - y - r])

    def wall_grad(z):
        g = np.zeros((4 * n, 3 * n))
        for k in range(n):
            g[k, 3 * k] = 1.0
            g[k, 3 * k + 2] = -1.0
            g[n + k, 3 * k] = -1.0
            g[n + k, 3 * k + 2] = -1.0
            g[2 * n + k, 3 * k + 1] = 1.0
            g[2 * n + k, 3 * k + 2] = -1.0
            g[3 * n + k, 3 * k + 1] = -1.0
            g[3 * n + k, 3 * k + 2] = -1.0
        return g

    def overlap(z):
        x, y, r = _pack(z, n)
        dx = x[ii] - x[jj]
        dy = y[ii] - y[jj]
        return dx * dx + dy * dy - (r[ii] + r[jj]) ** 2

    def overlap_grad(z):
        x, y, r = _pack(z, n)
        m = len(ii)
        g = np.zeros((m, 3 * n))
        dx = x[ii] - x[jj]
        dy = y[ii] - y[jj]
        rs = r[ii] + r[jj]
        for k in range(m):
            a, b = ii[k], jj[k]
            g[k, 3 * a] = 2 * dx[k]
            g[k, 3 * b] = -2 * dx[k]
            g[k, 3 * a + 1] = 2 * dy[k]
            g[k, 3 * b + 1] = -2 * dy[k]
            g[k, 3 * a + 2] = -2 * rs[k]
            g[k, 3 * b + 2] = -2 * rs[k]
        return g

    return [
        {'type': 'ineq', 'fun': wall, 'jac': wall_grad},
        {'type': 'ineq', 'fun': overlap, 'jac': overlap_grad},
    ]


def _repair(z, n):
    z = z.reshape(n, 3).copy()
    x, y, r = z[:, 0], z[:, 1], z[:, 2]
    r = np.maximum(r, 1e-6)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    for _ in range(300):
        tree = cKDTree(np.column_stack([x, y]))
        pairs = tree.query_pairs(r=0.5, output_type='ndarray')
        if len(pairs) == 0:
            break
        changed = False
        for i, j in pairs:
            d = np.hypot(x[i] - x[j], y[i] - y[j])
            s = r[i] + r[j]
            if d < s - 1e-15:
                if d < 1e-12:
                    r[i] *= 0.5
                    r[j] *= 0.5
                else:
                    f = (d / s) * (1.0 - 1e-12)
                    r[i] *= f
                    r[j] *= f
                changed = True
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
        if not changed:
            break
    z[:, 0], z[:, 1], z[:, 2] = x, y, r
    return z.reshape(-1)


def _lp_solve(centers, n):
    x = centers[:, 0]
    y = centers[:, 1]
    pairs = [(i, j) for i in range(n) for j in range(i + 1, n)]
    ii = np.array([p[0] for p in pairs])
    jj = np.array([p[1] for p in pairs])
    dx = x[ii] - x[jj]
    dy = y[ii] - y[jj]
    d = np.hypot(dx, dy)
    d = np.maximum(d, 1e-12)

    rows = []
    bvec = []
    for i in range(n):
        for val in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
            row = np.zeros(n)
            row[i] = 1.0
            rows.append(row)
            bvec.append(max(val, 0.0))
    for k in range(len(ii)):
        row = np.zeros(n)
        row[ii[k]] = 1.0
        row[jj[k]] = 1.0
        rows.append(row)
        bvec.append(d[k])
    A_ub = np.array(rows)
    b_ub = np.array(bvec)
    c = -np.ones(n)
    try:
        res = None
        try:
            res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=(0, None), method='highs',
                          options={'primal_feasibility_tolerance': 1e-12,
                                   'dual_feasibility_tolerance': 1e-12,
                                   'ipm_optimality_tolerance': 1e-12})
        except Exception:
            res = None
        if res is None or not res.success:
            res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=(0, None), method='highs')
        if not res.success:
            return None, -np.inf, None, ii, jj, d
        r = res.x
        val = -res.fun
        marg = None
        try:
            marg = res.ineqlin.marginals
        except Exception:
            marg = None
        return r, val, (marg, A_ub, b_ub), ii, jj, d
    except Exception:
        return None, -np.inf, None, ii, jj, d


def _lp_grad(centers, n, info, ii, jj, d):
    marg, A_ub, b_ub = info
    x = centers[:, 0]
    y = centers[:, 1]
    g = np.zeros((n, 2))
    if marg is None:
        return None
    lam = -np.asarray(marg)
    idx = 0
    for i in range(n):
        g[i, 0] += lam[idx]; idx += 1
        g[i, 0] -= lam[idx]; idx += 1
        g[i, 1] += lam[idx]; idx += 1
        g[i, 1] -= lam[idx]; idx += 1
    for k in range(len(ii)):
        lk = lam[idx]; idx += 1
        a, b = ii[k], jj[k]
        ddx = (x[a] - x[b]) / d[k]
        ddy = (y[a] - y[b]) / d[k]
        g[a, 0] += lk * ddx
        g[b, 0] -= lk * ddx
        g[a, 1] += lk * ddy
        g[b, 1] -= lk * ddy
    return g


def _certify_radii(xc, yc, r_init, n, max_passes=50):
    """Active-set lstsq radius solve + certification passes + greedy ULP increases."""
    x = np.asarray(xc, dtype=float).copy()
    y = np.asarray(yc, dtype=float).copy()
    r = np.maximum(np.asarray(r_init, dtype=float).copy(), 1e-11)
    tol = 1e-7

    # Build active set from r_init
    act_walls = []  # (i, w)
    for i in range(n):
        dists = (x[i], 1.0 - x[i], y[i], 1.0 - y[i])
        for w, dist in enumerate(dists):
            if dist - r[i] < tol:
                act_walls.append((i, w))
    act_pairs = []
    for i in range(n):
        for j in range(i + 1, n):
            d = math.hypot(x[i] - x[j], y[i] - y[j])
            if d - r[i] - r[j] < tol:
                act_pairs.append((i, j))

    # Solve lstsq for r on active equalities: A r = b
    rows = []
    bvec = []
    for (i, w) in act_walls:
        row = np.zeros(n)
        row[i] = 1.0
        if w == 0:
            bvec.append(x[i])
        elif w == 1:
            bvec.append(1.0 - x[i])
        elif w == 2:
            bvec.append(y[i])
        else:
            bvec.append(1.0 - y[i])
        rows.append(row)
    for (i, j) in act_pairs:
        row = np.zeros(n)
        row[i] = 1.0
        row[j] = 1.0
        bvec.append(math.hypot(x[i] - x[j], y[i] - y[j]))
        rows.append(row)

    if rows:
        A = np.array(rows)
        b = np.array(bvec)
        try:
            sol, *_ = np.linalg.lstsq(A, b, rcond=None)
            if np.all(np.isfinite(sol)):
                # Only adopt if it doesn't reduce sum
                cand = np.maximum(sol, 1e-11)
                if np.sum(cand) >= np.sum(r) - 1e-9:
                    r = cand
        except Exception:
            pass

    def full_slacks(rv):
        """Return list of (kind, data, slack) where slack = allowed - used."""
        out = []
        for i in range(n):
            for w, dist in enumerate((x[i], 1.0 - x[i], y[i], 1.0 - y[i])):
                out.append(('w', (i, w), dist - rv[i]))
        for i in range(n):
            for j in range(i + 1, n):
                d = math.hypot(x[i] - x[j], y[i] - y[j])
                out.append(('p', (i, j), d - rv[i] - rv[j]))
        return out

    # Certification passes: fix any negative slacks
    for _ in range(max_passes):
        slacks = full_slacks(r)
        violated = [(k, s) for k, s in slacks if s[2] < 0.0]
        if not violated:
            break
        # reduce smaller-radius participant
        for kind, data, slack in violated:
            excess = -slack
            if kind == 'w':
                i = data[0]
                r[i] = math.nextafter(r[i] - excess, 0.0)
            else:
                i, j = data
                if r[i] <= r[j]:
                    r[i] = math.nextafter(r[i] - excess, 0.0)
                else:
                    r[j] = math.nextafter(r[j] - excess, 0.0)
            r = np.maximum(r, 1e-11)

    # Greedy ULP radius increases, accepting only if fully feasible
    def feasible(rv):
        for i in range(n):
            for dist in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
                if rv[i] > dist:
                    return False
        for i in range(n):
            for j in range(i + 1, n):
                d = math.hypot(x[i] - x[j], y[i] - y[j])
                if rv[i] + rv[j] > d:
                    return False
        return True

    improved = True
    rounds = 0
    while improved and rounds < 20:
        improved = False
        rounds += 1
        for i in range(n):
            cand = math.nextafter(r[i], math.inf)
            trial = r.copy()
            trial[i] = cand
            if feasible(trial):
                r = trial
                improved = True

    return r


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32

    def time_left():
        return budget_seconds - (time.process_time() - t0)

    if start is not None:
        s = np.asarray(start, dtype=float).reshape(n, 3).copy()
        s[:, 2] = np.maximum(s[:, 2], 1e-6)
        z0 = _repair(s.reshape(-1), n)
    else:
        pts = []
        for j in range(7):
            for i in range(5):
                pts.append(((i + 0.5) / 5.0, (j + 0.5) / 7.0))
        pts = pts[:n]
        r0 = 1.0 / 14.0 - 1e-6
        z0 = np.array([[x, y, r0] for x, y in pts], dtype=float).reshape(-1)
        z0 = _repair(z0, n)

    z0 = z0.reshape(n, 3)
    centers = np.clip(z0[:, :2].copy(), 1e-4, 1.0 - 1e-4)

    best_centers = centers.copy()
    r, val, info, ii, jj, d = _lp_solve(centers, n)
    best_val_lp = val if r is not None else -np.inf

    lr = 0.002
    lp_phase_end = t0 + 0.5 * budget_seconds
    it = 0
    while time.process_time() < lp_phase_end and it < 500:
        it += 1
        r, val, info, ii, jj, d = _lp_solve(centers, n)
        if r is None:
            break
        if val > best_val_lp:
            best_val_lp = val
            best_centers = centers.copy()
        g = _lp_grad(centers, n, info, ii, jj, d)
        if g is None or not np.all(np.isfinite(g)):
            g = np.zeros((n, 2))
            eps = 1e-5
            for i in range(n):
                for k in range(2):
                    cp = centers.copy(); cm = centers.copy()
                    cp[i, k] += eps; cm[i, k] -= eps
                    _, vp, _, _, _, _ = _lp_solve(cp, n)
                    _, vm, _, _, _, _ = _lp_solve(cm, n)
                    if np.isfinite(vp) and np.isfinite(vm):
                        g[i, k] = (vp - vm) / (2 * eps)
        gn = np.linalg.norm(g)
        if gn < 1e-12:
            break
        step = lr
        accepted = False
        for _ in range(8):
            newc = centers + step * g
            rr = r
            newc[:, 0] = np.clip(newc[:, 0], rr + 1e-6, 1.0 - rr - 1e-6)
            newc[:, 1] = np.clip(newc[:, 1], rr + 1e-6, 1.0 - rr - 1e-6)
            _, vnew, _, _, _, _ = _lp_solve(newc, n)
            if np.isfinite(vnew) and vnew >= val - 1e-12:
                centers = newc
                accepted = True
                if vnew > best_val_lp:
                    best_val_lp = vnew
                    best_centers = newc.copy()
                break
            step *= 0.5
        if not accepted:
            lr *= 0.7
            if lr < 1e-6:
                break

    r_best, _, _, _, _, _ = _lp_solve(best_centers, n)
    if r_best is not None:
        zstart = np.column_stack([best_centers, np.maximum(r_best - 1e-9, 1e-10)])
        z0 = _repair(zstart.reshape(-1), n)

    bounds = []
    for _ in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-7, 0.5))

    cons = _constraints(n)

    best_z = z0.copy()
    best_val = -_neg_sum(best_z)

    def run_slsqp(zinit, maxiter, ftol=1e-13):
        try:
            res = minimize(
                _neg_sum, zinit, jac=_neg_sum_grad,
                method='SLSQP', bounds=bounds, constraints=cons,
                options={'maxiter': maxiter, 'ftol': ftol, 'disp': False},
            )
            if res.x is not None:
                zc = _repair(res.x, n)
                return zc, -_neg_sum(zc)
        except Exception:
            pass
        return None, -np.inf

    zc, val = run_slsqp(z0, 800)
    if val > best_val:
        best_val, best_z = val, zc

    rng = np.random.default_rng(2024)
    attempt = 0
    while time_left() > 0.8 and attempt < 30:
        attempt += 1
        scale = [0.005, 0.015, 0.03, 0.06][attempt % 4]
        zp = best_z.reshape(n, 3).copy()
        zp[:, 0] += rng.normal(0, scale, n)
        zp[:, 1] += rng.normal(0, scale, n)
        zp[:, 2] *= (1.0 + rng.normal(0, scale * 1.5, n))
        zp = _repair(zp.reshape(-1), n)
        zc, val = run_slsqp(zp, 400)
        if val > best_val:
            best_val, best_z = val, zc

    if time_left() > 0.3:
        zc, val = run_slsqp(best_z, 2000, ftol=1e-15)
        if zc is not None and val > best_val - 1e-6:
            best_z = zc
            best_val = max(best_val, val)

    # --- Final safety: minimal single-pass shrink using exact excess + one ULP nudge ---
    out = best_z.reshape(n, 3).copy()
    x = out[:, 0].copy()
    y = out[:, 1].copy()

    r_lp, _, _, _, _, _ = _lp_solve(np.column_stack([x, y]), n)
    if r_lp is not None:
        r = np.maximum(r_lp, 1e-11)
    else:
        r = np.maximum(out[:, 2].copy(), 1e-11)

    for i in range(n):
        for dist in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
            if r[i] > dist:
                r[i] = math.nextafter(dist, 0.0)
    r = np.maximum(r, 1e-11)

    for i in range(n):
        for j in range(i + 1, n):
            d = math.hypot(x[i] - x[j], y[i] - y[j])
            s = r[i] + r[j]
            if s > d:
                excess = s - d
                r[i] = math.nextafter(r[i] - excess / 2.0, 0.0)
                r[j] = math.nextafter(r[j] - excess / 2.0, 0.0)
    r = np.maximum(r, 1e-11)

    for i in range(n):
        for dist in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
            if r[i] > dist:
                r[i] = math.nextafter(r[i], 0.0)
    for i in range(n):
        for j in range(i + 1, n):
            d = math.hypot(x[i] - x[j], y[i] - y[j])
            if r[i] + r[j] > d:
                r[i] = math.nextafter(r[i], 0.0)
                r[j] = math.nextafter(r[j], 0.0)
    r = np.maximum(r, 1e-11)

    def final_shrink(xc, yc, r_in):
        r = np.maximum(r_in.copy(), 1e-11)
        for i in range(n):
            for dist in (xc[i], 1.0 - xc[i], yc[i], 1.0 - yc[i]):
                if r[i] > dist:
                    r[i] = math.nextafter(dist, 0.0)
        r = np.maximum(r, 1e-11)
        for i in range(n):
            for j in range(i + 1, n):
                d = math.hypot(xc[i] - xc[j], yc[i] - yc[j])
                s = r[i] + r[j]
                if s > d:
                    excess = s - d
                    r[i] = math.nextafter(r[i] - excess / 2.0, 0.0)
                    r[j] = math.nextafter(r[j] - excess / 2.0, 0.0)
        r = np.maximum(r, 1e-11)
        for i in range(n):
            for dist in (xc[i], 1.0 - xc[i], yc[i], 1.0 - yc[i]):
                if r[i] > dist:
                    r[i] = math.nextafter(r[i], 0.0)
        for i in range(n):
            for j in range(i + 1, n):
                d = math.hypot(xc[i] - xc[j], yc[i] - yc[j])
                if r[i] + r[j] > d:
                    r[i] = math.nextafter(r[i], 0.0)
                    r[j] = math.nextafter(r[j], 0.0)
        return np.maximum(r, 1e-11)

    r = final_shrink(x, y, r)
    cur_val = float(np.sum(r))
    cur_centers = np.column_stack([x, y]).copy()

    lp_count = 0
    improved = True
    while improved and lp_count < 200 and time_left() > 0.2:
        improved = False
        for i in range(n):
            if lp_count >= 200 or time_left() <= 0.2:
                break
            for k in range(2):
                if lp_count >= 200 or time_left() <= 0.2:
                    break
                base = cur_centers[i, k]
                for direction in (math.inf, -math.inf):
                    if lp_count >= 200 or time_left() <= 0.2:
                        break
                    cand = math.nextafter(base, direction)
                    if cand < 0.0 or cand > 1.0:
                        continue
                    trial = cur_centers.copy()
                    trial[i, k] = cand
                    r_try, v_try, _, _, _, _ = _lp_solve(trial, n)
                    lp_count += 1
                    if r_try is None or not np.isfinite(v_try):
                        continue
                    r_try = final_shrink(trial[:, 0], trial[:, 1], r_try)
                    v_try = float(np.sum(r_try))
                    if v_try > cur_val:
                        cur_val = v_try
                        cur_centers = trial
                        r = r_try
                        improved = True
                        break

    x = cur_centers[:, 0]
    y = cur_centers[:, 1]
    r = final_shrink(x, y, r)

    out = np.column_stack([x, y, r])

    # --- Newton/least-squares polish on active-set equality system ---
    if time_left() > 0.15:
        try:
            xc = out[:, 0].copy()
            yc = out[:, 1].copy()
            rc = out[:, 2].copy()
            tol = 1e-6
            act_pairs = []
            for i in range(n):
                for j in range(i + 1, n):
                    d = math.hypot(xc[i] - xc[j], yc[i] - yc[j])
                    if d - rc[i] - rc[j] < tol:
                        act_pairs.append((i, j))
            act_walls = []
            for i in range(n):
                for w, dist in enumerate((xc[i], 1.0 - xc[i], yc[i], 1.0 - yc[i])):
                    if dist - rc[i] < tol:
                        act_walls.append((i, w))
            if act_pairs or act_walls:
                ap_i = np.array([p[0] for p in act_pairs], dtype=int)
                ap_j = np.array([p[1] for p in act_pairs], dtype=int)
                aw_i = np.array([p[0] for p in act_walls], dtype=int)
                aw_w = np.array([p[1] for p in act_walls], dtype=int)
                npair = len(act_pairs)
                nwall = len(act_walls)

                def F(z):
                    zz = z.reshape(n, 3)
                    xx = zz[:, 0]; yy = zz[:, 1]; rr = zz[:, 2]
                    res = np.empty(npair + nwall)
                    if npair:
                        dx = xx[ap_i] - xx[ap_j]
                        dy = yy[ap_i] - yy[ap_j]
                        res[:npair] = np.hypot(dx, dy) - rr[ap_i] - rr[ap_j]
                    for k in range(nwall):
                        i = aw_i[k]; w = aw_w[k]
                        if w == 0:
                            dist = xx[i]
                        elif w == 1:
                            dist = 1.0 - xx[i]
                        elif w == 2:
                            dist = yy[i]
                        else:
                            dist = 1.0 - yy[i]
                        res[npair + k] = dist - rr[i]
                    return res

                def J(z):
                    zz = z.reshape(n, 3)
                    xx = zz[:, 0]; yy = zz[:, 1]
                    m = npair + nwall
                    Jm = np.zeros((m, 3 * n))
                    for k in range(npair):
                        a = ap_i[k]; b = ap_j[k]
                        dx = xx[a] - xx[b]; dy = yy[a] - yy[b]
                        d = math.hypot(dx, dy)
                        if d < 1e-12:
                            d = 1e-12
                        ux = dx / d; uy = dy / d
                        Jm[k, 3 * a] = ux
                        Jm[k, 3 * b] = -ux
                        Jm[k, 3 * a + 1] = uy
                        Jm[k, 3 * b + 1] = -uy
                        Jm[k, 3 * a + 2] = -1.0
                        Jm[k, 3 * b + 2] = -1.0
                    for k in range(nwall):
                        i = aw_i[k]; w = aw_w[k]
                        row = npair + k
                        if w == 0:
                            Jm[row, 3 * i] = 1.0
                        elif w == 1:
                            Jm[row, 3 * i] = -1.0
                        elif w == 2:
                            Jm[row, 3 * i + 1] = 1.0
                        else:
                            Jm[row, 3 * i + 1] = -1.0
                        Jm[row, 3 * i + 2] = -1.0
                    return Jm

                z_init = out.reshape(-1).copy()
                res = least_squares(
                    F, z_init, jac=J, method='lm',
                    ftol=1e-15, xtol=1e-15, gtol=1e-15, max_nfev=200,
                )
                if res.success and res.x is not None:
                    cand = res.x.reshape(n, 3).copy()
                    cand[:, 2] = np.maximum(cand[:, 2], 1e-11)
                    xc2 = cand[:, 0].copy()
                    yc2 = cand[:, 1].copy()
                    rc2 = cand[:, 2].copy()
                    r2 = final_shrink(xc2, yc2, rc2)
                    if float(np.sum(r2)) > float(np.sum(out[:, 2])):
                        out = np.column_stack([xc2, yc2, r2])
        except Exception:
            pass

    # --- NEW: certified active-set radius solve + certification passes ---
    try:
        xf = out[:, 0].copy()
        yf = out[:, 1].copy()
        rf = out[:, 2].copy()
        r_cert = _certify_radii(xf, yf, rf, n, max_passes=50)
        # Final exact feasibility check before adopting
        ok = True
        for i in range(n):
            for dist in (xf[i], 1.0 - xf[i], yf[i], 1.0 - yf[i]):
                if r_cert[i] > dist or r_cert[i] <= 0.0:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            for i in range(n):
                if not ok:
                    break
                for j in range(i + 1, n):
                    d = math.hypot(xf[i] - xf[j], yf[i] - yf[j])
                    if r_cert[i] + r_cert[j] > d:
                        ok = False
                        break
        if ok and float(np.sum(r_cert)) >= float(np.sum(out[:, 2])) - 1e-15:
            out = np.column_stack([xf, yf, r_cert])
    except Exception:
        pass

    return out

import numpy as np
import time
import math
from scipy.optimize import linprog
from scipy.spatial import cKDTree


def _lp_solve(centers, n, ii, jj):
    x = centers[:, 0]
    y = centers[:, 1]
    dx = x[ii] - x[jj]
    dy = y[ii] - y[jj]
    d = np.maximum(np.hypot(dx, dy), 1e-12)

    m = len(ii)
    A = np.zeros((4 * n + m, n))
    b = np.zeros(4 * n + m)
    for i in range(n):
        A[4 * i, i] = 1.0;     b[4 * i] = max(x[i], 0.0)
        A[4 * i + 1, i] = 1.0; b[4 * i + 1] = max(1.0 - x[i], 0.0)
        A[4 * i + 2, i] = 1.0; b[4 * i + 2] = max(y[i], 0.0)
        A[4 * i + 3, i] = 1.0; b[4 * i + 3] = max(1.0 - y[i], 0.0)
    for k in range(m):
        A[4 * n + k, ii[k]] = 1.0
        A[4 * n + k, jj[k]] = 1.0
        b[4 * n + k] = d[k]
    try:
        res = linprog(-np.ones(n), A_ub=A, b_ub=b, bounds=(0, None), method='highs')
        if not res.success:
            return None, -np.inf
        return res.x, -res.fun
    except Exception:
        return None, -np.inf


def _shrink(xc, yc, r_in, n):
    r = np.maximum(r_in.copy(), 1e-11)
    for i in range(n):
        for dist in (xc[i], 1.0 - xc[i], yc[i], 1.0 - yc[i]):
            if r[i] > dist:
                r[i] = math.nextafter(dist, 0.0)
    r = np.maximum(r, 1e-11)
    for i in range(n):
        for j in range(i + 1, n):
            d = math.hypot(xc[i] - xc[j], yc[i] - yc[j])
            s = r[i] + r[j]
            if s > d:
                exc = s - d
                r[i] = math.nextafter(r[i] - exc / 2.0, 0.0)
                r[j] = math.nextafter(r[j] - exc / 2.0, 0.0)
    r = np.maximum(r, 1e-11)
    for i in range(n):
        for dist in (xc[i], 1.0 - xc[i], yc[i], 1.0 - yc[i]):
            if r[i] > dist:
                r[i] = math.nextafter(r[i], 0.0)
    for i in range(n):
        for j in range(i + 1, n):
            d = math.hypot(xc[i] - xc[j], yc[i] - yc[j])
            if r[i] + r[j] > d:
                r[i] = math.nextafter(r[i], 0.0)
                r[j] = math.nextafter(r[j], 0.0)
    return np.maximum(r, 1e-11)


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32

    def left():
        return budget_seconds - (time.process_time() - t0)

    pairs = [(i, j) for i in range(n) for j in range(i + 1, n)]
    ii = np.array([p[0] for p in pairs])
    jj = np.array([p[1] for p in pairs])

    if start is not None:
        s = np.asarray(start, dtype=float).reshape(n, 3).copy()
        s[:, 2] = np.maximum(s[:, 2], 1e-6)
        xc = s[:, 0].copy()
        yc = s[:, 1].copy()
        rc = s[:, 2].copy()
    else:
        xc = np.zeros(n); yc = np.zeros(n)
        k = 0
        for j in range(7):
            for i in range(5):
                if k < n:
                    xc[k] = (i + 0.5) / 5.0
                    yc[k] = (j + 0.5) / 7.0
                    k += 1
        rc = np.full(n, 1.0 / 14.0 - 1e-6)

    # Repair into a valid configuration
    rc = np.maximum(rc, 1e-6)
    xc = np.clip(xc, rc, 1.0 - rc)
    yc = np.clip(yc, rc, 1.0 - rc)
    for _ in range(200):
        tree = cKDTree(np.column_stack([xc, yc]))
        prs = tree.query_pairs(r=0.5, output_type='ndarray')
        if len(prs) == 0:
            break
        ch = False
        for i, j in prs:
            d = math.hypot(xc[i] - xc[j], yc[i] - yc[j])
            ssum = rc[i] + rc[j]
            if d < ssum - 1e-15:
                if d < 1e-12:
                    rc[i] *= 0.5; rc[j] *= 0.5
                else:
                    f = (d / ssum) * (1.0 - 1e-12)
                    rc[i] *= f; rc[j] *= f
                ch = True
        xc = np.clip(xc, rc, 1.0 - rc)
        yc = np.clip(yc, rc, 1.0 - rc)
        if not ch:
            break

    centers = np.column_stack([xc, yc])

    # LP-based coordinate ascent on centers (the main new idea).
    # For fixed centers, maximize sum r via LP. Then do coordinate ascent
    # on centers using LP value, with adaptive step sizes.
    r, v = _lp_solve(centers, n, ii, jj)
    if r is None:
        r = rc.copy(); v = float(np.sum(r))
    best_c = centers.copy()
    best_v = v
    best_r = r.copy() if r is not None else rc.copy()

    # Phase 1: coordinate ascent with LP objective
    step = 0.02
    phase1_end = t0 + 0.55 * budget_seconds
    while time.process_time() < phase1_end and left() > 0.3:
        improved = False
        for i in range(n):
            if time.process_time() > phase1_end or left() < 0.3:
                break
            for k in range(2):
                for direction in (1.0, -1.0):
                    if time.process_time() > phase1_end or left() < 0.3:
                        break
                    trial = centers.copy()
                    trial[i, k] += direction * step
                    if trial[i, k] < 0 or trial[i, k] > 1:
                        continue
                    rt, vt = _lp_solve(trial, n, ii, jj)
                    if rt is not None and vt > v + 1e-14:
                        centers = trial
                        v = vt
                        r = rt
                        improved = True
                        if vt > best_v:
                            best_v = vt
                            best_c = trial.copy()
                            best_r = rt.copy()
        if not improved:
            step *= 0.5
            if step < 1e-7:
                break

    centers = best_c
    r = best_r

    # Phase 2: random perturbations + LP coordinate ascent from best.
    rng = np.random.default_rng(12345)
    while left() > 0.25:
        scale = rng.choice([0.003, 0.01, 0.03, 0.06])
        trial = centers + rng.normal(0, scale, centers.shape)
        trial = np.clip(trial, 1e-4, 1.0 - 1e-4)
        rt, vt = _lp_solve(trial, n, ii, jj)
        if rt is None or vt <= best_v + 1e-13:
            continue
        centers = trial; v = vt; r = rt
        best_v = vt; best_c = trial.copy(); best_r = rt.copy()
        # local polish
        step = 0.01
        for _ in range(300):
            if left() < 0.25:
                break
            improved = False
            for i in range(n):
                if left() < 0.25:
                    break
                for k in range(2):
                    for direction in (1.0, -1.0):
                        if left() < 0.25:
                            break
                        tr = centers.copy()
                        tr[i, k] += direction * step
                        if tr[i, k] < 0 or tr[i, k] > 1:
                            continue
                        rt2, vt2 = _lp_solve(tr, n, ii, jj)
                        if rt2 is not None and vt2 > v + 1e-14:
                            centers = tr; v = vt2; r = rt2
                            improved = True
                            if vt2 > best_v:
                                best_v = vt2
                                best_c = tr.copy()
                                best_r = rt2.copy()
            if not improved:
                step *= 0.5
                if step < 1e-8:
                    break

    # Final: shrink radii for strict validity
    x = best_c[:, 0]
    y = best_c[:, 1]
    r = _shrink(x, y, best_r, n)
    out = np.column_stack([x, y, r])

    return out

import numpy as np
import time
import math
from scipy.optimize import minimize, linprog, least_squares
from scipy.spatial import cKDTree


def _pack(z, n):
    z = z.reshape(n, 3)
    return z[:, 0], z[:, 1], z[:, 2]


def _neg_sum(z):
    return -np.sum(z.reshape(-1, 3)[:, 2])


def _neg_sum_grad(z):
    g = np.zeros_like(z)
    g.reshape(-1, 3)[:, 2] = -1.0
    return g


def _constraints(n):
    pairs = [(i, j) for i in range(n) for j in range(i + 1, n)]
    ii = np.array([p[0] for p in pairs])
    jj = np.array([p[1] for p in pairs])

    def wall(z):
        x, y, r = _pack(z, n)
        return np.concatenate([x - r, 1.0 - x - r, y - r, 1.0 - y - r])

    def wall_grad(z):
        g = np.zeros((4 * n, 3 * n))
        for k in range(n):
            g[k, 3 * k] = 1.0
            g[k, 3 * k + 2] = -1.0
            g[n + k, 3 * k] = -1.0
            g[n + k, 3 * k + 2] = -1.0
            g[2 * n + k, 3 * k + 1] = 1.0
            g[2 * n + k, 3 * k + 2] = -1.0
            g[3 * n + k, 3 * k + 1] = -1.0
            g[3 * n + k, 3 * k + 2] = -1.0
        return g

    def overlap(z):
        x, y, r = _pack(z, n)
        dx = x[ii] - x[jj]
        dy = y[ii] - y[jj]
        return dx * dx + dy * dy - (r[ii] + r[jj]) ** 2

    def overlap_grad(z):
        x, y, r = _pack(z, n)
        m = len(ii)
        g = np.zeros((m, 3 * n))
        dx = x[ii] - x[jj]
        dy = y[ii] - y[jj]
        rs = r[ii] + r[jj]
        for k in range(m):
            a, b = ii[k], jj[k]
            g[k, 3 * a] = 2 * dx[k]
            g[k, 3 * b] = -2 * dx[k]
            g[k, 3 * a + 1] = 2 * dy[k]
            g[k, 3 * b + 1] = -2 * dy[k]
            g[k, 3 * a + 2] = -2 * rs[k]
            g[k, 3 * b + 2] = -2 * rs[k]
        return g

    return [
        {'type': 'ineq', 'fun': wall, 'jac': wall_grad},
        {'type': 'ineq', 'fun': overlap, 'jac': overlap_grad},
    ]


def _repair(z, n):
    z = z.reshape(n, 3).copy()
    x, y, r = z[:, 0], z[:, 1], z[:, 2]
    r = np.maximum(r, 1e-6)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    for _ in range(300):
        tree = cKDTree(np.column_stack([x, y]))
        pairs = tree.query_pairs(r=0.5, output_type='ndarray')
        if len(pairs) == 0:
            break
        changed = False
        for i, j in pairs:
            d = np.hypot(x[i] - x[j], y[i] - y[j])
            s = r[i] + r[j]
            if d < s - 1e-15:
                if d < 1e-12:
                    r[i] *= 0.5
                    r[j] *= 0.5
                else:
                    f = (d / s) * (1.0 - 1e-12)
                    r[i] *= f
                    r[j] *= f
                changed = True
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
        if not changed:
            break
    z[:, 0], z[:, 1], z[:, 2] = x, y, r
    return z.reshape(-1)


def _lp_solve(centers, n):
    x = centers[:, 0]
    y = centers[:, 1]
    pairs = [(i, j) for i in range(n) for j in range(i + 1, n)]
    ii = np.array([p[0] for p in pairs])
    jj = np.array([p[1] for p in pairs])
    dx = x[ii] - x[jj]
    dy = y[ii] - y[jj]
    d = np.hypot(dx, dy)
    d = np.maximum(d, 1e-12)

    rows = []
    bvec = []
    for i in range(n):
        for val in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
            row = np.zeros(n)
            row[i] = 1.0
            rows.append(row)
            bvec.append(max(val, 0.0))
    for k in range(len(ii)):
        row = np.zeros(n)
        row[ii[k]] = 1.0
        row[jj[k]] = 1.0
        rows.append(row)
        bvec.append(d[k])
    A_ub = np.array(rows)
    b_ub = np.array(bvec)
    c = -np.ones(n)
    try:
        res = None
        try:
            res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=(0, None), method='highs',
                          options={'primal_feasibility_tolerance': 1e-12,
                                   'dual_feasibility_tolerance': 1e-12,
                                   'ipm_optimality_tolerance': 1e-12})
        except Exception:
            res = None
        if res is None or not res.success:
            res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=(0, None), method='highs')
        if not res.success:
            return None, -np.inf, None, ii, jj, d
        r = res.x
        val = -res.fun
        marg = None
        try:
            marg = res.ineqlin.marginals
        except Exception:
            marg = None
        return r, val, (marg, A_ub, b_ub), ii, jj, d
    except Exception:
        return None, -np.inf, None, ii, jj, d


def _lp_grad(centers, n, info, ii, jj, d):
    marg, A_ub, b_ub = info
    x = centers[:, 0]
    y = centers[:, 1]
    g = np.zeros((n, 2))
    if marg is None:
        return None
    lam = -np.asarray(marg)
    idx = 0
    for i in range(n):
        g[i, 0] += lam[idx]; idx += 1
        g[i, 0] -= lam[idx]; idx += 1
        g[i, 1] += lam[idx]; idx += 1
        g[i, 1] -= lam[idx]; idx += 1
    for k in range(len(ii)):
        lk = lam[idx]; idx += 1
        a, b = ii[k], jj[k]
        ddx = (x[a] - x[b]) / d[k]
        ddy = (y[a] - y[b]) / d[k]
        g[a, 0] += lk * ddx
        g[b, 0] -= lk * ddx
        g[a, 1] += lk * ddy
        g[b, 1] -= lk * ddy
    return g


def _exact_active_radius(x, y, n, tol=1e-6):
    """Solve for radii from active-set equalities via lstsq, then certify."""
    # Active walls: r_i = dist
    wall_rows = []
    wall_rhs = []
    for i in range(n):
        dists = (x[i], 1.0 - x[i], y[i], 1.0 - y[i])
        for dist in dists:
            if dist < tol:  # near-touching wall (r_lp ~ dist)
                row = np.zeros(n)
                row[i] = 1.0
                wall_rows.append(row)
                wall_rhs.append(max(dist, 0.0))
    # Active pairs: r_i + r_j = d
    pair_rows = []
    pair_rhs = []
    for i in range(n):
        for j in range(i + 1, n):
            d = math.hypot(x[i] - x[j], y[i] - y[j])
            # active if pair gap small relative to typical radius
            if d < 2 * tol + 0.25:  # generous; lstsq handles overdetermined
                # only include if likely active: check with current r_lp later
                pass
    # We need r_lp to decide pair activity; caller passes via closure - redo below
    return wall_rows, wall_rhs


def _certified_shrink(x, y, r, n, max_passes=50):
    r = np.maximum(r.copy(), 1e-11)
    for _ in range(max_passes):
        violated = False
        for i in range(n):
            for dist in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
                if r[i] > dist:
                    r[i] = math.nextafter(dist, 0.0)
                    violated = True
        r = np.maximum(r, 1e-11)
        for i in range(n):
            for j in range(i + 1, n):
                d = math.hypot(x[i] - x[j], y[i] - y[j])
                s = r[i] + r[j]
                if s > d:
                    excess = s - d
                    r[i] = math.nextafter(r[i] - excess / 2.0, 0.0)
                    r[j] = math.nextafter(r[j] - excess / 2.0, 0.0)
                    violated = True
        r = np.maximum(r, 1e-11)
        if not violated:
            break
    return r


def _all_ok(x, y, r, n):
    for i in range(n):
        if r[i] <= 0:
            return False
        for dist in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
            if r[i] > dist:
                return False
    for i in range(n):
        for j in range(i + 1, n):
            d = math.hypot(x[i] - x[j], y[i] - y[j])
            if r[i] + r[j] > d:
                return False
    return True


def _greedy_ulp_recover(x, y, r, n):
    r = r.copy()
    for i in range(n):
        cand = math.nextafter(r[i], math.inf)
        if cand <= 0:
            continue
        # check walls
        ok = True
        for dist in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
            if cand > dist:
                ok = False
                break
        if ok:
            for j in range(n):
                if j == i:
                    continue
                d = math.hypot(x[i] - x[j], y[i] - y[j])
                if cand + r[j] > d:
                    ok = False
                    break
        if ok:
            r[i] = cand
    return r


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32

    def time_left():
        return budget_seconds - (time.process_time() - t0)

    if start is not None:
        s = np.asarray(start, dtype=float).reshape(n, 3).copy()
        s[:, 2] = np.maximum(s[:, 2], 1e-6)
        z0 = _repair(s.reshape(-1), n)
    else:
        pts = []
        for j in range(7):
            for i in range(5):
                pts.append(((i + 0.5) / 5.0, (j + 0.5) / 7.0))
        pts = pts[:n]
        r0 = 1.0 / 14.0 - 1e-6
        z0 = np.array([[x, y, r0] for x, y in pts], dtype=float).reshape(-1)
        z0 = _repair(z0, n)

    z0 = z0.reshape(n, 3)
    centers = np.clip(z0[:, :2].copy(), 1e-4, 1.0 - 1e-4)

    best_centers = centers.copy()
    r, val, info, ii, jj, d = _lp_solve(centers, n)
    best_val_lp = val if r is not None else -np.inf

    lr = 0.002
    lp_phase_end = t0 + 0.5 * budget_seconds
    it = 0
    while time.process_time() < lp_phase_end and it < 500:
        it += 1
        r, val, info, ii, jj, d = _lp_solve(centers, n)
        if r is None:
            break
        if val > best_val_lp:
            best_val_lp = val
            best_centers = centers.copy()
        g = _lp_grad(centers, n, info, ii, jj, d)
        if g is None or not np.all(np.isfinite(g)):
            g = np.zeros((n, 2))
            eps = 1e-5
            for i in range(n):
                for k in range(2):
                    cp = centers.copy(); cm = centers.copy()
                    cp[i, k] += eps; cm[i, k] -= eps
                    _, vp, _, _, _, _ = _lp_solve(cp, n)
                    _, vm, _, _, _, _ = _lp_solve(cm, n)
                    if np.isfinite(vp) and np.isfinite(vm):
                        g[i, k] = (vp - vm) / (2 * eps)
        gn = np.linalg.norm(g)
        if gn < 1e-12:
            break
        step = lr
        accepted = False
        for _ in range(8):
            newc = centers + step * g
            rr = r
            newc[:, 0] = np.clip(newc[:, 0], rr + 1e-6, 1.0 - rr - 1e-6)
            newc[:, 1] = np.clip(newc[:, 1], rr + 1e-6, 1.0 - rr - 1e-6)
            _, vnew, _, _, _, _ = _lp_solve(newc, n)
            if np.isfinite(vnew) and vnew >= val - 1e-12:
                centers = newc
                accepted = True
                if vnew > best_val_lp:
                    best_val_lp = vnew
                    best_centers = newc.copy()
                break
            step *= 0.5
        if not accepted:
            lr *= 0.7
            if lr < 1e-6:
                break

    r_best, _, _, _, _, _ = _lp_solve(best_centers, n)
    if r_best is not None:
        zstart = np.column_stack([best_centers, np.maximum(r_best - 1e-9, 1e-10)])
        z0 = _repair(zstart.reshape(-1), n)

    bounds = []
    for _ in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-7, 0.5))

    cons = _constraints(n)

    best_z = z0.copy()
    best_val = -_neg_sum(best_z)

    def run_slsqp(zinit, maxiter, ftol=1e-13):
        try:
            res = minimize(
                _neg_sum, zinit, jac=_neg_sum_grad,
                method='SLSQP', bounds=bounds, constraints=cons,
                options={'maxiter': maxiter, 'ftol': ftol, 'disp': False},
            )
            if res.x is not None:
                zc = _repair(res.x, n)
                return zc, -_neg_sum(zc)
        except Exception:
            pass
        return None, -np.inf

    zc, val = run_slsqp(z0, 800)
    if val > best_val:
        best_val, best_z = val, zc

    rng = np.random.default_rng(2024)
    attempt = 0
    while time_left() > 0.8 and attempt < 30:
        attempt += 1
        scale = [0.005, 0.015, 0.03, 0.06][attempt % 4]
        zp = best_z.reshape(n, 3).copy()
        zp[:, 0] += rng.normal(0, scale, n)
        zp[:, 1] += rng.normal(0, scale, n)
        zp[:, 2] *= (1.0 + rng.normal(0, scale * 1.5, n))
        zp = _repair(zp.reshape(-1), n)
        zc, val = run_slsqp(zp, 400)
        if val > best_val:
            best_val, best_z = val, zc

    if time_left() > 0.3:
        zc, val = run_slsqp(best_z, 2000, ftol=1e-15)
        if zc is not None and val > best_val - 1e-6:
            best_z = zc
            best_val = max(best_val, val)

    # --- Final safety: minimal single-pass shrink using exact excess + one ULP nudge ---
    out = best_z.reshape(n, 3).copy()
    x = out[:, 0].copy()
    y = out[:, 1].copy()

    # (1) Recompute radii from LP at final centers
    r_lp, _, _, _, _, _ = _lp_solve(np.column_stack([x, y]), n)
    if r_lp is not None:
        r = np.maximum(r_lp, 1e-11)
    else:
        r = np.maximum(out[:, 2].copy(), 1e-11)

    # --- NEW: exact active-set radius solve via lstsq, then certified shrink + ULP recovery ---
    try:
        tol_act = 1e-6
        rows = []
        rhs = []
        # Active walls: dist - r_lp[i] < tol
        for i in range(n):
            for dist in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
                if dist - r_lp[i] < tol_act:
                    row = np.zeros(n)
                    row[i] = 1.0
                    rows.append(row)
                    rhs.append(max(dist, 0.0))
        # Active pairs
        for i in range(n):
            for j in range(i + 1, n):
                dij = math.hypot(x[i] - x[j], y[i] - y[j])
                if dij - r_lp[i] - r_lp[j] < tol_act:
                    row = np.zeros(n)
                    row[i] = 1.0
                    row[j] = 1.0
                    rows.append(row)
                    rhs.append(dij)
        if rows:
            A = np.array(rows)
            b = np.array(rhs)
            sol, _, _, _ = np.linalg.lstsq(A, b, rcond=None)
            r_new = np.maximum(sol, 1e-11)
        else:
            r_new = r.copy()
        r_new = _certified_shrink(x, y, r_new, n, max_passes=50)
        r_new = _greedy_ulp_recover(x, y, r_new, n)
        r_new = _certified_shrink(x, y, r_new, n, max_passes=50)
        if _all_ok(x, y, r_new, n) and float(np.sum(r_new)) >= float(np.sum(r)):
            r = r_new
    except Exception:
        pass

    # (2) Wall constraints: shrink radius to wall distance, one ULP below
    for i in range(n):
        for dist in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
            if r[i] > dist:
                r[i] = math.nextafter(dist, 0.0)
    r = np.maximum(r, 1e-11)

    # (2b) Pair constraints: single pass, exact excess, split half, one ULP below
    for i in range(n):
        for j in range(i + 1, n):
            d = math.hypot(x[i] - x[j], y[i] - y[j])
            s = r[i] + r[j]
            if s > d:
                excess = s - d
                r[i] = math.nextafter(r[i] - excess / 2.0, 0.0)
                r[j] = math.nextafter(r[j] - excess / 2.0, 0.0)
    r = np.maximum(r, 1e-11)

    # (3) Final check: any remaining violation gets one more nextafter
    for i in range(n):
        for dist in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
            if r[i] > dist:
                r[i] = math.nextafter(r[i], 0.0)
    for i in range(n):
        for j in range(i + 1, n):
            d = math.hypot(x[i] - x[j], y[i] - y[j])
            if r[i] + r[j] > d:
                r[i] = math.nextafter(r[i], 0.0)
                r[j] = math.nextafter(r[j], 0.0)
    r = np.maximum(r, 1e-11)

    # --- ULP-scale coordinate ascent on centers with exact LP re-solve ---
    def final_shrink(xc, yc, r_in):
        r = np.maximum(r_in.copy(), 1e-11)
        for i in range(n):
            for dist in (xc[i], 1.0 - xc[i], yc[i], 1.0 - yc[i]):
                if r[i] > dist:
                    r[i] = math.nextafter(dist, 0.0)
        r = np.maximum(r, 1e-11)
        for i in range(n):
            for j in range(i + 1, n):
                d = math.hypot(xc[i] - xc[j], yc[i] - yc[j])
                s = r[i] + r[j]
                if s > d:
                    excess = s - d
                    r[i] = math.nextafter(r[i] - excess / 2.0, 0.0)
                    r[j] = math.nextafter(r[j] - excess / 2.0, 0.0)
        r = np.maximum(r, 1e-11)
        for i in range(n):
            for dist in (xc[i], 1.0 - xc[i], yc[i], 1.0 - yc[i]):
                if r[i] > dist:
                    r[i] = math.nextafter(r[i], 0.0)
        for i in range(n):
            for j in range(i + 1, n):
                d = math.hypot(xc[i] - xc[j], yc[i] - yc[j])
                if r[i] + r[j] > d:
                    r[i] = math.nextafter(r[i], 0.0)
                    r[j] = math.nextafter(r[j], 0.0)
        return np.maximum(r, 1e-11)

    r = final_shrink(x, y, r)
    cur_val = float(np.sum(r))
    cur_centers = np.column_stack([x, y]).copy()

    lp_count = 0
    improved = True
    while improved and lp_count < 200 and time_left() > 0.2:
        improved = False
        for i in range(n):
            if lp_count >= 200 or time_left() <= 0.2:
                break
            for k in range(2):
                if lp_count >= 200 or time_left() <= 0.2:
                    break
                base = cur_centers[i, k]
                for direction in (math.inf, -math.inf):
                    if lp_count >= 200 or time_left() <= 0.2:
                        break
                    cand = math.nextafter(base, direction)
                    if cand < 0.0 or cand > 1.0:
                        continue
                    trial = cur_centers.copy()
                    trial[i, k] = cand
                    r_try, v_try, _, _, _, _ = _lp_solve(trial, n)
                    lp_count += 1
                    if r_try is None or not np.isfinite(v_try):
                        continue
                    r_try = final_shrink(trial[:, 0], trial[:, 1], r_try)
                    v_try = float(np.sum(r_try))
                    if v_try > cur_val:
                        cur_val = v_try
                        cur_centers = trial
                        r = r_try
                        improved = True
                        break

    x = cur_centers[:, 0]
    y = cur_centers[:, 1]
    r = final_shrink(x, y, r)

    out = np.column_stack([x, y, r])

    # --- Newton/least-squares polish on active-set equality system ---
    if time_left() > 0.15:
        try:
            xc = out[:, 0].copy()
            yc = out[:, 1].copy()
            rc = out[:, 2].copy()
            tol = 1e-6
            act_pairs = []
            for i in range(n):
                for j in range(i + 1, n):
                    d = math.hypot(xc[i] - xc[j], yc[i] - yc[j])
                    if d - rc[i] - rc[j] < tol:
                        act_pairs.append((i, j))
            act_walls = []
            for i in range(n):
                for w, dist in enumerate((xc[i], 1.0 - xc[i], yc[i], 1.0 - yc[i])):
                    if dist - rc[i] < tol:
                        act_walls.append((i, w))
            if act_pairs or act_walls:
                ap_i = np.array([p[0] for p in act_pairs], dtype=int)
                ap_j = np.array([p[1] for p in act_pairs], dtype=int)
                aw_i = np.array([p[0] for p in act_walls], dtype=int)
                aw_w = np.array([p[1] for p in act_walls], dtype=int)
                npair = len(act_pairs)
                nwall = len(act_walls)

                def F(z):
                    zz = z.reshape(n, 3)
                    xx = zz[:, 0]; yy = zz[:, 1]; rr = zz[:, 2]
                    res = np.empty(npair + nwall)
                    if npair:
                        dx = xx[ap_i] - xx[ap_j]
                        dy = yy[ap_i] - yy[ap_j]
                        res[:npair] = np.hypot(dx, dy) - rr[ap_i] - rr[ap_j]
                    for k in range(nwall):
                        i = aw_i[k]; w = aw_w[k]
                        if w == 0:
                            dist = xx[i]
                        elif w == 1:
                            dist = 1.0 - xx[i]
                        elif w == 2:
                            dist = yy[i]
                        else:
                            dist = 1.0 - yy[i]
                        res[npair + k] = dist - rr[i]
                    return res

                def J(z):
                    zz = z.reshape(n, 3)
                    xx = zz[:, 0]; yy = zz[:, 1]
                    m = npair + nwall
                    Jm = np.zeros((m, 3 * n))
                    for k in range(npair):
                        a = ap_i[k]; b = ap_j[k]
                        dx = xx[a] - xx[b]; dy = yy[a] - yy[b]
                        d = math.hypot(dx, dy)
                        if d < 1e-12:
                            d = 1e-12
                        ux = dx / d; uy = dy / d
                        Jm[k, 3 * a] = ux
                        Jm[k, 3 * b] = -ux
                        Jm[k, 3 * a + 1] = uy
                        Jm[k, 3 * b + 1] = -uy
                        Jm[k, 3 * a + 2] = -1.0
                        Jm[k, 3 * b + 2] = -1.0
                    for k in range(nwall):
                        i = aw_i[k]; w = aw_w[k]
                        row = npair + k
                        if w == 0:
                            Jm[row, 3 * i] = 1.0
                        elif w == 1:
                            Jm[row, 3 * i] = -1.0
                        elif w == 2:
                            Jm[row, 3 * i + 1] = 1.0
                        else:
                            Jm[row, 3 * i + 1] = -1.0
                        Jm[row, 3 * i + 2] = -1.0
                    return Jm

                z_init = out.reshape(-1).copy()
                res = least_squares(
                    F, z_init, jac=J, method='lm',
                    ftol=1e-15, xtol=1e-15, gtol=1e-15, max_nfev=200,
                )
                if res.success and res.x is not None:
                    cand = res.x.reshape(n, 3).copy()
                    cand[:, 2] = np.maximum(cand[:, 2], 1e-11)
                    xc2 = cand[:, 0].copy()
                    yc2 = cand[:, 1].copy()
                    rc2 = cand[:, 2].copy()
                    r2 = final_shrink(xc2, yc2, rc2)
                    if float(np.sum(r2)) > float(np.sum(out[:, 2])):
                        out = np.column_stack([xc2, yc2, r2])
        except Exception:
            pass

    return out

import numpy as np
import time
import math
from scipy.optimize import linprog
from scipy.spatial import cKDTree


def _lp_solve(centers, n, ii, jj):
    x = centers[:, 0]
    y = centers[:, 1]
    dx = x[ii] - x[jj]
    dy = y[ii] - y[jj]
    d = np.maximum(np.hypot(dx, dy), 1e-12)

    m = len(ii)
    A = np.zeros((4 * n + m, n))
    b = np.zeros(4 * n + m)
    for i in range(n):
        A[4 * i, i] = 1.0;     b[4 * i] = max(x[i], 0.0)
        A[4 * i + 1, i] = 1.0; b[4 * i + 1] = max(1.0 - x[i], 0.0)
        A[4 * i + 2, i] = 1.0; b[4 * i + 2] = max(y[i], 0.0)
        A[4 * i + 3, i] = 1.0; b[4 * i + 3] = max(1.0 - y[i], 0.0)
    for k in range(m):
        A[4 * n + k, ii[k]] = 1.0
        A[4 * n + k, jj[k]] = 1.0
        b[4 * n + k] = d[k]
    try:
        res = linprog(-np.ones(n), A_ub=A, b_ub=b, bounds=(0, None), method='highs')
        if not res.success:
            return None, -np.inf, None
        return res.x, -res.fun, -np.asarray(res.ineqlin.marginals)
    except Exception:
        return None, -np.inf, None


def _shrink(xc, yc, r_in, n):
    r = np.maximum(r_in.copy(), 1e-11)
    for i in range(n):
        for dist in (xc[i], 1.0 - xc[i], yc[i], 1.0 - yc[i]):
            if r[i] > dist:
                r[i] = math.nextafter(dist, 0.0)
    r = np.maximum(r, 1e-11)
    for i in range(n):
        for j in range(i + 1, n):
            d = math.hypot(xc[i] - xc[j], yc[i] - yc[j])
            s = r[i] + r[j]
            if s > d:
                exc = s - d
                r[i] = math.nextafter(r[i] - exc / 2.0, 0.0)
                r[j] = math.nextafter(r[j] - exc / 2.0, 0.0)
    r = np.maximum(r, 1e-11)
    for i in range(n):
        for dist in (xc[i], 1.0 - xc[i], yc[i], 1.0 - yc[i]):
            if r[i] > dist:
                r[i] = math.nextafter(r[i], 0.0)
    for i in range(n):
        for j in range(i + 1, n):
            d = math.hypot(xc[i] - xc[j], yc[i] - yc[j])
            if r[i] + r[j] > d:
                r[i] = math.nextafter(r[i], 0.0)
                r[j] = math.nextafter(r[j], 0.0)
    return np.maximum(r, 1e-11)


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32

    def left():
        return budget_seconds - (time.process_time() - t0)

    pairs = [(i, j) for i in range(n) for j in range(i + 1, n)]
    ii = np.array([p[0] for p in pairs])
    jj = np.array([p[1] for p in pairs])

    if start is not None:
        s = np.asarray(start, dtype=float).reshape(n, 3).copy()
        s[:, 2] = np.maximum(s[:, 2], 1e-6)
        xc = s[:, 0].copy(); yc = s[:, 1].copy(); rc = s[:, 2].copy()
    else:
        xc = np.zeros(n); yc = np.zeros(n); k = 0
        for j in range(7):
            for i in range(5):
                if k < n:
                    xc[k] = (i + 0.5) / 5.0
                    yc[k] = (j + 0.5) / 7.0
                    k += 1
        rc = np.full(n, 1.0 / 14.0 - 1e-6)

    rc = np.maximum(rc, 1e-6)
    xc = np.clip(xc, rc, 1.0 - rc)
    yc = np.clip(yc, rc, 1.0 - rc)
    for _ in range(200):
        tree = cKDTree(np.column_stack([xc, yc]))
        prs = tree.query_pairs(r=0.5, output_type='ndarray')
        if len(prs) == 0:
            break
        ch = False
        for i, j in prs:
            d = math.hypot(xc[i] - xc[j], yc[i] - yc[j])
            ssum = rc[i] + rc[j]
            if d < ssum - 1e-15:
                if d < 1e-12:
                    rc[i] *= 0.5; rc[j] *= 0.5
                else:
                    f = (d / ssum) * (1.0 - 1e-12)
                    rc[i] *= f; rc[j] *= f
                ch = True
        xc = np.clip(xc, rc, 1.0 - rc)
        yc = np.clip(yc, rc, 1.0 - rc)
        if not ch:
            break

    centers = np.column_stack([xc, yc])
    r, v, lam = _lp_solve(centers, n, ii, jj)
    if r is None:
        r = rc.copy(); v = float(np.sum(r)); lam = None
    best_c = centers.copy(); best_v = v; best_r = r.copy()

    # Gradient helper using LP duals (marginals)
    def lp_grad(centers):
        x = centers[:, 0]; y = centers[:, 1]
        dx = x[ii] - x[jj]; dy = y[ii] - y[jj]
        d = np.maximum(np.hypot(dx, dy), 1e-12)
        rt, vt, mg = _lp_solve(centers, n, ii, jj)
        if rt is None:
            return None, None, None
        g = np.zeros((n, 2))
        idx = 0
        for i in range(n):
            g[i, 0] += mg[idx] - mg[idx + 1]; idx += 2
            g[i, 1] += mg[idx] - mg[idx + 1]; idx += 2
        for k in range(len(ii)):
            lk = mg[idx]; idx += 1
            if lk == 0.0:
                continue
            a, b = ii[k], jj[k]
            ux = (x[a] - x[b]) / d[k]; uy = (y[a] - y[b]) / d[k]
            g[a, 0] += lk * ux; g[b, 0] -= lk * ux
            g[a, 1] += lk * uy; g[b, 1] -= lk * uy
        return g, rt, vt

    # Phase A: gradient ascent on the LP objective (fast, uses duals).
    cur_c = best_c.copy(); cur_v = best_v
    lr = 0.05
    phaseA_end = t0 + 0.55 * budget_seconds
    while time.process_time() < phaseA_end and left() > 0.4:
        g, rt, vt = lp_grad(cur_c)
        if g is None:
            break
        gn = np.linalg.norm(g)
        if gn < 1e-14:
            break
        gdir = g / gn
        step = lr
        accepted = False
        for _ in range(12):
            trial = cur_c + step * gdir
            trial[:, 0] = np.clip(trial[:, 0], 1e-4, 1.0 - 1e-4)
            trial[:, 1] = np.clip(trial[:, 1], 1e-4, 1.0 - 1e-4)
            rt2, vt2, _ = _lp_solve(trial, n, ii, jj)
            if rt2 is not None and vt2 > cur_v + 1e-13:
                cur_c = trial; cur_v = vt2
                if vt2 > best_v:
                    best_v = vt2; best_c = trial.copy(); best_r = rt2.copy()
                accepted = True
                lr = min(lr * 1.2, 0.2)
                break
            step *= 0.5
        if not accepted:
            lr *= 0.5
            if lr < 1e-6:
                break

    # Phase B: stochastic block coordinate ascent with LP objective.
    rng = np.random.default_rng(987654321)
    cur_c = best_c.copy(); cur_v = best_v
    damp = 0.02
    while left() > 0.35:
        k = int(rng.integers(1, 6))
        idxs = rng.choice(n, size=k, replace=False)
        trial = cur_c.copy()
        amp = damp * (0.3 + rng.random())
        trial[idxs] += rng.normal(0, amp, (k, 2))
        trial[:, 0] = np.clip(trial[:, 0], 1e-4, 1.0 - 1e-4)
        trial[:, 1] = np.clip(trial[:, 1], 1e-4, 1.0 - 1e-4)
        rt, vt, _ = _lp_solve(trial, n, ii, jj)
        if rt is None:
            continue
        if vt > cur_v - 1e-12:
            cur_c = trial; cur_v = vt
            if vt > best_v:
                best_v = vt; best_c = trial.copy(); best_r = rt.copy()
        if rng.random() < 0.03:
            damp = max(damp * 0.9, 0.001)

    # Phase C: final coordinate-ascent polish on the best configuration.
    centers = best_c.copy(); v = best_v; r = best_r.copy()
    step = 0.005
    while left() > 0.15:
        improved = False
        for i in range(n):
            if left() < 0.15:
                break
            for k2 in range(2):
                for direction in (1.0, -1.0):
                    if left() < 0.15:
                        break
                    trial = centers.copy()
                    trial[i, k2] += direction * step
                    if trial[i, k2] < 1e-4 or trial[i, k2] > 1.0 - 1e-4:
                        continue
                    rt, vt, _ = _lp_solve(trial, n, ii, jj)
                    if rt is not None and vt > v + 1e-14:
                        centers = trial; v = vt; r = rt
                        improved = True
                        if vt > best_v:
                            best_v = vt; best_c = trial.copy(); best_r = rt.copy()
        if not improved:
            step *= 0.5
            if step < 1e-7:
                break

    x = best_c[:, 0]
    y = best_c[:, 1]
    r = _shrink(x, y, best_r, n)
    return np.column_stack([x, y, r])

import numpy as np
import time
import math
from scipy.optimize import linprog


def _build_lp(n):
    ii, jj = [], []
    for i in range(n):
        for j in range(i + 1, n):
            ii.append(i); jj.append(j)
    return np.array(ii), np.array(jj)


def _lp_radii(centers, n, ii, jj, A_ub=None, b_ub=None):
    x = centers[:, 0]; y = centers[:, 1]
    if A_ub is None:
        A_ub = np.zeros((4 * n + len(ii), n))
        for i in range(n):
            A_ub[4*i, i] = 1.0
            A_ub[4*i+1, i] = 1.0
            A_ub[4*i+2, i] = 1.0
            A_ub[4*i+3, i] = 1.0
        for k in range(len(ii)):
            A_ub[4*n+k, ii[k]] = 1.0
            A_ub[4*n+k, jj[k]] = 1.0
    b_ub = np.empty(4 * n + len(ii))
    b_ub[0:4*n:4] = np.maximum(x, 0.0)
    b_ub[1:4*n:4] = np.maximum(1.0 - x, 0.0)
    b_ub[2:4*n:4] = np.maximum(y, 0.0)
    b_ub[3:4*n:4] = np.maximum(1.0 - y, 0.0)
    dx = x[ii] - x[jj]; dy = y[ii] - y[jj]
    b_ub[4*n:] = np.maximum(np.hypot(dx, dy), 1e-12)
    try:
        res = linprog(-np.ones(n), A_ub=A_ub, b_ub=b_ub,
                      bounds=(0, None), method='highs')
        if not res.success:
            return None, -np.inf, None
        return res.x, -res.fun, res
    except Exception:
        return None, -np.inf, None


def _shrink(x, y, r, n):
    r = np.maximum(r.copy(), 1e-11)
    for i in range(n):
        for dist in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
            if r[i] > dist:
                r[i] = math.nextafter(dist, 0.0)
    r = np.maximum(r, 1e-11)
    for i in range(n):
        for j in range(i + 1, n):
            d = math.hypot(x[i] - x[j], y[i] - y[j])
            s = r[i] + r[j]
            if s > d:
                excess = s - d
                r[i] = math.nextafter(r[i] - excess / 2.0, 0.0)
                r[j] = math.nextafter(r[j] - excess / 2.0, 0.0)
    r = np.maximum(r, 1e-11)
    for i in range(n):
        for dist in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
            if r[i] > dist:
                r[i] = math.nextafter(r[i], 0.0)
    for i in range(n):
        for j in range(i + 1, n):
            d = math.hypot(x[i] - x[j], y[i] - y[j])
            if r[i] + r[j] > d:
                r[i] = math.nextafter(r[i], 0.0)
                r[j] = math.nextafter(r[j], 0.0)
    return np.maximum(r, 1e-11)


def _lp_grad(centers, n, ii, jj, res):
    x = centers[:, 0]; y = centers[:, 1]
    dx = x[ii] - x[jj]; dy = y[ii] - y[jj]
    d = np.maximum(np.hypot(dx, dy), 1e-12)
    try:
        lam = -np.asarray(res.ineqlin.marginals)
    except Exception:
        return None
    g = np.zeros((n, 2))
    idx = 0
    for i in range(n):
        g[i, 0] += lam[idx]; idx += 1
        g[i, 0] -= lam[idx]; idx += 1
        g[i, 1] += lam[idx]; idx += 1
        g[i, 1] -= lam[idx]; idx += 1
    ux = dx / d; uy = dy / d
    for k in range(len(ii)):
        lk = lam[idx]; idx += 1
        a, b = ii[k], jj[k]
        g[a, 0] += lk * ux[k]; g[b, 0] -= lk * ux[k]
        g[a, 1] += lk * uy[k]; g[b, 1] -= lk * uy[k]
    return g


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    ii, jj = _build_lp(n)

    def time_left():
        return budget_seconds - (time.process_time() - t0)

    if start is not None:
        s = np.asarray(start, dtype=float).reshape(n, 3)
        centers = np.clip(s[:, :2].copy(), 1e-4, 1.0 - 1e-4)
    else:
        pts = []
        for j in range(7):
            for i in range(5):
                pts.append(((i + 0.5) / 5.0, (j + 0.5) / 7.0))
        centers = np.array(pts[:n], dtype=float)

    r0, v0, res0 = _lp_radii(centers, n, ii, jj)
    if r0 is None:
        r0 = np.full(n, 0.05); v0 = float(r0.sum())
    best_centers = centers.copy()
    best_val = v0
    cur_centers = centers.copy()
    cur_val = v0

    rng = np.random.default_rng(12345)

    # Phase A: random coordinate ascent (block moves)
    damp = 0.03
    while time_left() > 0.55 * budget_seconds:
        k = int(rng.integers(1, 5))
        idxs = rng.choice(n, size=k, replace=False)
        trial = cur_centers.copy()
        amp = damp * (0.3 + rng.random())
        trial[idxs] += rng.normal(0, amp, (k, 2))
        np.clip(trial[:, 0], 1e-4, 1.0 - 1e-4, out=trial[:, 0])
        np.clip(trial[:, 1], 1e-4, 1.0 - 1e-4, out=trial[:, 1])
        rt, vt, _ = _lp_radii(trial, n, ii, jj)
        if rt is None:
            continue
        if vt > cur_val - 1e-12:
            cur_centers = trial
            cur_val = vt
            if vt > best_val:
                best_val = vt
                best_centers = trial.copy()
        if rng.random() < 0.02:
            damp = max(damp * 0.85, 0.0015)

    # Phase B: gradient ascent using LP marginals
    cur_centers = best_centers.copy()
    cur_val = best_val
    lr = 0.003
    while time_left() > 0.30 * budget_seconds:
        r, v, res = _lp_radii(cur_centers, n, ii, jj)
        if r is None:
            break
        g = _lp_grad(cur_centers, n, ii, jj, res)
        if g is None:
            break
        gn = np.linalg.norm(g)
        if gn < 1e-12:
            break
        step = lr
        accepted = False
        for _ in range(10):
            trial = cur_centers + step * g
            np.clip(trial[:, 0], r + 1e-6, 1.0 - r - 1e-6, out=trial[:, 0])
            np.clip(trial[:, 1], r + 1e-6, 1.0 - r - 1e-6, out=trial[:, 1])
            rt, vt, _ = _lp_radii(trial, n, ii, jj)
            if rt is not None and np.isfinite(vt) and vt >= v - 1e-13:
                cur_centers = trial
                cur_val = vt
                accepted = True
                if vt > best_val:
                    best_val = vt
                    best_centers = trial.copy()
                break
            step *= 0.5
        if not accepted:
            lr *= 0.6
            if lr < 1e-7:
                break

    # ULP polish on best centers
    x = best_centers[:, 0].copy()
    y = best_centers[:, 1].copy()
    r_lp, _, _ = _lp_radii(best_centers, n, ii, jj)
    if r_lp is None:
        r_lp = np.full(n, 0.05)
    r = _shrink(x, y, r_lp, n)
    cur_val = float(r.sum())
    centers = np.column_stack([x, y]).copy()

    count = 0
    lp_budget = 800
    improved = True
    while improved and count < lp_budget and time_left() > 0.08:
        improved = False
        for i in range(n):
            if count >= lp_budget or time_left() <= 0.08:
                break
            for k in range(2):
                if count >= lp_budget or time_left() <= 0.08:
                    break
                base = centers[i, k]
                for direction in (math.inf, -math.inf):
                    if count >= lp_budget or time_left() <= 0.08:
                        break
                    cand = math.nextafter(base, direction)
                    if cand < 0.0 or cand > 1.0:
                        continue
                    trial = centers.copy()
                    trial[i, k] = cand
                    rt, vt, _ = _lp_radii(trial, n, ii, jj)
                    count += 1
                    if rt is None or not np.isfinite(vt):
                        continue
                    rt2 = _shrink(trial[:, 0], trial[:, 1], rt, n)
                    if float(rt2.sum()) > cur_val:
                        cur_val = float(rt2.sum())
                        centers = trial
                        r = rt2
                        improved = True
                        break

    x = centers[:, 0]; y = centers[:, 1]
    r = _shrink(x, y, r, n)
    return np.column_stack([x, y, r])

import numpy as np
import time
import math
from scipy.optimize import minimize, linprog, least_squares
from scipy.spatial import cKDTree


def _pack(z, n):
    z = z.reshape(n, 3)
    return z[:, 0], z[:, 1], z[:, 2]


def _neg_sum(z):
    return -np.sum(z.reshape(-1, 3)[:, 2])


def _neg_sum_grad(z):
    g = np.zeros_like(z)
    g.reshape(-1, 3)[:, 2] = -1.0
    return g


def _constraints(n):
    pairs = [(i, j) for i in range(n) for j in range(i + 1, n)]
    ii = np.array([p[0] for p in pairs])
    jj = np.array([p[1] for p in pairs])

    def wall(z):
        x, y, r = _pack(z, n)
        return np.concatenate([x - r, 1.0 - x - r, y - r, 1.0 - y - r])

    def wall_grad(z):
        g = np.zeros((4 * n, 3 * n))
        for k in range(n):
            g[k, 3 * k] = 1.0
            g[k, 3 * k + 2] = -1.0
            g[n + k, 3 * k] = -1.0
            g[n + k, 3 * k + 2] = -1.0
            g[2 * n + k, 3 * k + 1] = 1.0
            g[2 * n + k, 3 * k + 2] = -1.0
            g[3 * n + k, 3 * k + 1] = -1.0
            g[3 * n + k, 3 * k + 2] = -1.0
        return g

    def overlap(z):
        x, y, r = _pack(z, n)
        dx = x[ii] - x[jj]
        dy = y[ii] - y[jj]
        return dx * dx + dy * dy - (r[ii] + r[jj]) ** 2

    def overlap_grad(z):
        x, y, r = _pack(z, n)
        m = len(ii)
        g = np.zeros((m, 3 * n))
        dx = x[ii] - x[jj]
        dy = y[ii] - y[jj]
        rs = r[ii] + r[jj]
        for k in range(m):
            a, b = ii[k], jj[k]
            g[k, 3 * a] = 2 * dx[k]
            g[k, 3 * b] = -2 * dx[k]
            g[k, 3 * a + 1] = 2 * dy[k]
            g[k, 3 * b + 1] = -2 * dy[k]
            g[k, 3 * a + 2] = -2 * rs[k]
            g[k, 3 * b + 2] = -2 * rs[k]
        return g

    return [
        {'type': 'ineq', 'fun': wall, 'jac': wall_grad},
        {'type': 'ineq', 'fun': overlap, 'jac': overlap_grad},
    ]


def _repair(z, n):
    z = z.reshape(n, 3).copy()
    x, y, r = z[:, 0], z[:, 1], z[:, 2]
    r = np.maximum(r, 1e-6)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    for _ in range(300):
        tree = cKDTree(np.column_stack([x, y]))
        pairs = tree.query_pairs(r=0.5, output_type='ndarray')
        if len(pairs) == 0:
            break
        changed = False
        for i, j in pairs:
            d = np.hypot(x[i] - x[j], y[i] - y[j])
            s = r[i] + r[j]
            if d < s - 1e-15:
                if d < 1e-12:
                    r[i] *= 0.5
                    r[j] *= 0.5
                else:
                    f = (d / s) * (1.0 - 1e-12)
                    r[i] *= f
                    r[j] *= f
                changed = True
        x = np.clip(x, r, 1.0 - r)
        y = np.clip(y, r, 1.0 - r)
        if not changed:
            break
    z[:, 0], z[:, 1], z[:, 2] = x, y, r
    return z.reshape(-1)


def _lp_solve(centers, n):
    x = centers[:, 0]
    y = centers[:, 1]
    pairs = [(i, j) for i in range(n) for j in range(i + 1, n)]
    ii = np.array([p[0] for p in pairs])
    jj = np.array([p[1] for p in pairs])
    dx = x[ii] - x[jj]
    dy = y[ii] - y[jj]
    d = np.hypot(dx, dy)
    d = np.maximum(d, 1e-12)

    rows = []
    bvec = []
    for i in range(n):
        for val in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
            row = np.zeros(n)
            row[i] = 1.0
            rows.append(row)
            bvec.append(max(val, 0.0))
    for k in range(len(ii)):
        row = np.zeros(n)
        row[ii[k]] = 1.0
        row[jj[k]] = 1.0
        rows.append(row)
        bvec.append(d[k])
    A_ub = np.array(rows)
    b_ub = np.array(bvec)
    c = -np.ones(n)
    try:
        res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=(0, None), method='highs')
        if not res.success:
            return None, -np.inf, None, ii, jj, d
        r = res.x
        val = -res.fun
        marg = None
        try:
            marg = res.ineqlin.marginals
        except Exception:
            marg = None
        return r, val, (marg, A_ub, b_ub), ii, jj, d
    except Exception:
        return None, -np.inf, None, ii, jj, d


def _lp_grad(centers, n, info, ii, jj, d):
    marg, A_ub, b_ub = info
    x = centers[:, 0]
    y = centers[:, 1]
    g = np.zeros((n, 2))
    if marg is None:
        return None
    lam = -np.asarray(marg)
    idx = 0
    for i in range(n):
        g[i, 0] += lam[idx]; idx += 1
        g[i, 0] -= lam[idx]; idx += 1
        g[i, 1] += lam[idx]; idx += 1
        g[i, 1] -= lam[idx]; idx += 1
    for k in range(len(ii)):
        lk = lam[idx]; idx += 1
        a, b = ii[k], jj[k]
        ddx = (x[a] - x[b]) / d[k]
        ddy = (y[a] - y[b]) / d[k]
        g[a, 0] += lk * ddx
        g[b, 0] -= lk * ddx
        g[a, 1] += lk * ddy
        g[b, 1] -= lk * ddy
    return g


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32

    def time_left():
        return budget_seconds - (time.process_time() - t0)

    if start is not None:
        s = np.asarray(start, dtype=float).reshape(n, 3).copy()
        s[:, 2] = np.maximum(s[:, 2], 1e-6)
        z0 = _repair(s.reshape(-1), n)
    else:
        pts = []
        for j in range(7):
            for i in range(5):
                pts.append(((i + 0.5) / 5.0, (j + 0.5) / 7.0))
        pts = pts[:n]
        r0 = 1.0 / 14.0 - 1e-6
        z0 = np.array([[x, y, r0] for x, y in pts], dtype=float).reshape(-1)
        z0 = _repair(z0, n)

    z0 = z0.reshape(n, 3)
    centers = np.clip(z0[:, :2].copy(), 1e-4, 1.0 - 1e-4)

    best_centers = centers.copy()
    r, val, info, ii, jj, d = _lp_solve(centers, n)
    best_val_lp = val if r is not None else -np.inf

    lr = 0.002
    lp_phase_end = t0 + 0.5 * budget_seconds
    it = 0
    while time.process_time() < lp_phase_end and it < 500:
        it += 1
        r, val, info, ii, jj, d = _lp_solve(centers, n)
        if r is None:
            break
        if val > best_val_lp:
            best_val_lp = val
            best_centers = centers.copy()
        g = _lp_grad(centers, n, info, ii, jj, d)
        if g is None or not np.all(np.isfinite(g)):
            g = np.zeros((n, 2))
            eps = 1e-5
            for i in range(n):
                for k in range(2):
                    cp = centers.copy(); cm = centers.copy()
                    cp[i, k] += eps; cm[i, k] -= eps
                    _, vp, _, _, _, _ = _lp_solve(cp, n)
                    _, vm, _, _, _, _ = _lp_solve(cm, n)
                    if np.isfinite(vp) and np.isfinite(vm):
                        g[i, k] = (vp - vm) / (2 * eps)
        gn = np.linalg.norm(g)
        if gn < 1e-12:
            break
        step = lr
        accepted = False
        for _ in range(8):
            newc = centers + step * g
            rr = r
            newc[:, 0] = np.clip(newc[:, 0], rr + 1e-6, 1.0 - rr - 1e-6)
            newc[:, 1] = np.clip(newc[:, 1], rr + 1e-6, 1.0 - rr - 1e-6)
            _, vnew, _, _, _, _ = _lp_solve(newc, n)
            if np.isfinite(vnew) and vnew >= val - 1e-12:
                centers = newc
                accepted = True
                if vnew > best_val_lp:
                    best_val_lp = vnew
                    best_centers = newc.copy()
                break
            step *= 0.5
        if not accepted:
            lr *= 0.7
            if lr < 1e-6:
                break

    r_best, _, _, _, _, _ = _lp_solve(best_centers, n)
    if r_best is not None:
        zstart = np.column_stack([best_centers, np.maximum(r_best - 1e-9, 1e-10)])
        z0 = _repair(zstart.reshape(-1), n)

    bounds = []
    for _ in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-7, 0.5))

    cons = _constraints(n)

    best_z = z0.copy()
    best_val = -_neg_sum(best_z)

    def run_slsqp(zinit, maxiter, ftol=1e-13):
        try:
            res = minimize(
                _neg_sum, zinit, jac=_neg_sum_grad,
                method='SLSQP', bounds=bounds, constraints=cons,
                options={'maxiter': maxiter, 'ftol': ftol, 'disp': False},
            )
            if res.x is not None:
                zc = _repair(res.x, n)
                return zc, -_neg_sum(zc)
        except Exception:
            pass
        return None, -np.inf

    zc, val = run_slsqp(z0, 800)
    if val > best_val:
        best_val, best_z = val, zc

    rng = np.random.default_rng(2024)
    attempt = 0
    while time_left() > 0.8 and attempt < 30:
        attempt += 1
        scale = [0.005, 0.015, 0.03, 0.06][attempt % 4]
        zp = best_z.reshape(n, 3).copy()
        zp[:, 0] += rng.normal(0, scale, n)
        zp[:, 1] += rng.normal(0, scale, n)
        zp[:, 2] *= (1.0 + rng.normal(0, scale * 1.5, n))
        zp = _repair(zp.reshape(-1), n)
        zc, val = run_slsqp(zp, 400)
        if val > best_val:
            best_val, best_z = val, zc

    if time_left() > 0.3:
        zc, val = run_slsqp(best_z, 2000, ftol=1e-15)
        if zc is not None and val > best_val - 1e-6:
            best_z = zc
            best_val = max(best_val, val)

    # --- Final safety: minimal single-pass shrink using exact excess + one ULP nudge ---
    out = best_z.reshape(n, 3).copy()
    x = out[:, 0].copy()
    y = out[:, 1].copy()

    # (1) Recompute radii from LP at final centers
    r_lp, _, _, _, _, _ = _lp_solve(np.column_stack([x, y]), n)
    if r_lp is not None:
        r = np.maximum(r_lp, 1e-11)
    else:
        r = np.maximum(out[:, 2].copy(), 1e-11)

    # --- NEW: center-only ULP repair loop to reduce final_shrink loss ---
    if r_lp is not None:
        xc = x.copy()
        yc = y.copy()
        rc = np.maximum(r_lp.copy(), 1e-11)

        def all_ok(xa, ya, ra):
            # walls
            for i in range(n):
                if ra[i] > xa[i] or ra[i] > 1.0 - xa[i] or ra[i] > ya[i] or ra[i] > 1.0 - ya[i]:
                    return False
            # pairs
            for i in range(n):
                for j in range(i + 1, n):
                    dd = math.hypot(xa[i] - xa[j], ya[i] - ya[j])
                    if ra[i] + ra[j] > dd:
                        return False
            return True

        for _pass in range(200):
            if time_left() <= 0.15:
                break
            viol = []
            for i in range(n):
                for j in range(i + 1, n):
                    dd = math.hypot(xc[i] - xc[j], yc[i] - yc[j])
                    if dd < rc[i] + rc[j]:
                        viol.append((i, j, dd))
            if not viol:
                break
            any_moved = False
            for (i, j, dd) in viol:
                dx = xc[i] - xc[j]
                dy = yc[i] - yc[j]
                if dd < 1e-15:
                    # pick arbitrary direction
                    ux, uy = 1.0, 0.0
                else:
                    ux = dx / dd
                    uy = dy / dd
                # try moving i along -u and j along +u, one ULP each on x and/or y
                # candidate moves: for each axis component, nextafter in the needed direction
                # Build candidate new positions
                cand_i = []
                cand_j = []
                # x component
                if ux > 0:
                    cand_i.append(('x', math.nextafter(xc[i], -math.inf)))
                    cand_j.append(('x', math.nextafter(xc[j], math.inf)))
                elif ux < 0:
                    cand_i.append(('x', math.nextafter(xc[i], math.inf)))
                    cand_j.append(('x', math.nextafter(xc[j], -math.inf)))
                if uy > 0:
                    cand_i.append(('y', math.nextafter(yc[i], -math.inf)))
                    cand_j.append(('y', math.nextafter(yc[j], math.inf)))
                elif uy < 0:
                    cand_i.append(('y', math.nextafter(yc[i], math.inf)))
                    cand_j.append(('y', math.nextafter(yc[j], -math.inf)))

                moved = False
                # try single-axis moves first
                for (ax_i, vi) in cand_i:
                    for (ax_j, vj) in cand_j:
                        if ax_i != ax_j:
                            continue
                        xn = xc.copy(); yn = yc.copy()
                        if ax_i == 'x':
                            xn[i] = vi; xn[j] = vj
                        else:
                            yn[i] = vi; yn[j] = vj
                        if all_ok(xn, yn, rc):
                            xc, yc = xn, yn
                            moved = True
                            break
                    if moved:
                        break
                if not moved:
                    # try combined x+y move
                    if len(cand_i) >= 2 and len(cand_j) >= 2:
                        xn = xc.copy(); yn = yc.copy()
                        for (ax_i, vi) in cand_i:
                            if ax_i == 'x': xn[i] = vi
                            else: yn[i] = vi
                        for (ax_j, vj) in cand_j:
                            if ax_j == 'x': xn[j] = vj
                            else: yn[j] = vj
                        if all_ok(xn, yn, rc):
                            xc, yc = xn, yn
                            moved = True
                if moved:
                    any_moved = True
            if not any_moved:
                break
        x = xc
        y = yc
        r = rc

    # (2) Wall constraints: shrink radius to wall distance, one ULP below
    for i in range(n):
        for dist in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
            if r[i] > dist:
                r[i] = math.nextafter(dist, 0.0)
    r = np.maximum(r, 1e-11)

    # (2b) Pair constraints: single pass, exact excess, split half, one ULP below
    for i in range(n):
        for j in range(i + 1, n):
            d = math.hypot(x[i] - x[j], y[i] - y[j])
            s = r[i] + r[j]
            if s > d:
                excess = s - d
                r[i] = math.nextafter(r[i] - excess / 2.0, 0.0)
                r[j] = math.nextafter(r[j] - excess / 2.0, 0.0)
    r = np.maximum(r, 1e-11)

    # (3) Final check: any remaining violation gets one more nextafter
    for i in range(n):
        for dist in (x[i], 1.0 - x[i], y[i], 1.0 - y[i]):
            if r[i] > dist:
                r[i] = math.nextafter(r[i], 0.0)
    for i in range(n):
        for j in range(i + 1, n):
            d = math.hypot(x[i] - x[j], y[i] - y[j])
            if r[i] + r[j] > d:
                r[i] = math.nextafter(r[i], 0.0)
                r[j] = math.nextafter(r[j], 0.0)
    r = np.maximum(r, 1e-11)

    # --- ULP-scale coordinate ascent on centers with exact LP re-solve ---
    def final_shrink(xc, yc, r_in):
        r = np.maximum(r_in.copy(), 1e-11)
        for i in range(n):
            for dist in (xc[i], 1.0 - xc[i], yc[i], 1.0 - yc[i]):
                if r[i] > dist:
                    r[i] = math.nextafter(dist, 0.0)
        r = np.maximum(r, 1e-11)
        for i in range(n):
            for j in range(i + 1, n):
                d = math.hypot(xc[i] - xc[j], yc[i] - yc[j])
                s = r[i] + r[j]
                if s > d:
                    excess = s - d
                    r[i] = math.nextafter(r[i] - excess / 2.0, 0.0)
                    r[j] = math.nextafter(r[j] - excess / 2.0, 0.0)
        r = np.maximum(r, 1e-11)
        for i in range(n):
            for dist in (xc[i], 1.0 - xc[i], yc[i], 1.0 - yc[i]):
                if r[i] > dist:
                    r[i] = math.nextafter(r[i], 0.0)
        for i in range(n):
            for j in range(i + 1, n):
                d = math.hypot(xc[i] - xc[j], yc[i] - yc[j])
                if r[i] + r[j] > d:
                    r[i] = math.nextafter(r[i], 0.0)
                    r[j] = math.nextafter(r[j], 0.0)
        return np.maximum(r, 1e-11)

    r = final_shrink(x, y, r)
    cur_val = float(np.sum(r))
    cur_centers = np.column_stack([x, y]).copy()

    lp_count = 0
    improved = True
    while improved and lp_count < 200 and time_left() > 0.2:
        improved = False
        for i in range(n):
            if lp_count >= 200 or time_left() <= 0.2:
                break
            for k in range(2):
                if lp_count >= 200 or time_left() <= 0.2:
                    break
                base = cur_centers[i, k]
                for direction in (math.inf, -math.inf):
                    if lp_count >= 200 or time_left() <= 0.2:
                        break
                    cand = math.nextafter(base, direction)
                    if cand < 0.0 or cand > 1.0:
                        continue
                    trial = cur_centers.copy()
                    trial[i, k] = cand
                    r_try, v_try, _, _, _, _ = _lp_solve(trial, n)
                    lp_count += 1
                    if r_try is None or not np.isfinite(v_try):
                        continue
                    r_try = final_shrink(trial[:, 0], trial[:, 1], r_try)
                    v_try = float(np.sum(r_try))
                    if v_try > cur_val:
                        cur_val = v_try
                        cur_centers = trial
                        r = r_try
                        improved = True
                        break

    x = cur_centers[:, 0]
    y = cur_centers[:, 1]
    r = final_shrink(x, y, r)

    out = np.column_stack([x, y, r])

    # --- Newton/least-squares polish on active-set equality system ---
    if time_left() > 0.15:
        try:
            xc = out[:, 0].copy()
            yc = out[:, 1].copy()
            rc = out[:, 2].copy()
            tol = 1e-6
            act_pairs = []
            for i in range(n):
                for j in range(i + 1, n):
                    d = math.hypot(xc[i] - xc[j], yc[i] - yc[j])
                    if d - rc[i] - rc[j] < tol:
                        act_pairs.append((i, j))
            act_walls = []
            for i in range(n):
                for w, dist in enumerate((xc[i], 1.0 - xc[i], yc[i], 1.0 - yc[i])):
                    if dist - rc[i] < tol:
                        act_walls.append((i, w))
            if act_pairs or act_walls:
                ap_i = np.array([p[0] for p in act_pairs], dtype=int)
                ap_j = np.array([p[1] for p in act_pairs], dtype=int)
                aw_i = np.array([p[0] for p in act_walls], dtype=int)
                aw_w = np.array([p[1] for p in act_walls], dtype=int)
                npair = len(act_pairs)
                nwall = len(act_walls)

                def F(z):
                    zz = z.reshape(n, 3)
                    xx = zz[:, 0]; yy = zz[:, 1]; rr = zz[:, 2]
                    res = np.empty(npair + nwall)
                    if npair:
                        dx = xx[ap_i] - xx[ap_j]
                        dy = yy[ap_i] - yy[ap_j]
                        res[:npair] = np.hypot(dx, dy) - rr[ap_i] - rr[ap_j]
                    for k in range(nwall):
                        i = aw_i[k]; w = aw_w[k]
                        if w == 0:
                            dist = xx[i]
                        elif w == 1:
                            dist = 1.0 - xx[i]
                        elif w == 2:
                            dist = yy[i]
                        else:
                            dist = 1.0 - yy[i]
                        res[npair + k] = dist - rr[i]
                    return res

                def J(z):
                    zz = z.reshape(n, 3)
                    xx = zz[:, 0]; yy = zz[:, 1]
                    m = npair + nwall
                    Jm = np.zeros((m, 3 * n))
                    for k in range(npair):
                        a = ap_i[k]; b = ap_j[k]
                        dx = xx[a] - xx[b]; dy = yy[a] - yy[b]
                        d = math.hypot(dx, dy)
                        if d < 1e-12:
                            d = 1e-12
                        ux = dx / d; uy = dy / d
                        Jm[k, 3 * a] = ux
                        Jm[k, 3 * b] = -ux
                        Jm[k, 3 * a + 1] = uy
                        Jm[k, 3 * b + 1] = -uy
                        Jm[k, 3 * a + 2] = -1.0
                        Jm[k, 3 * b + 2] = -1.0
                    for k in range(nwall):
                        i = aw_i[k]; w = aw_w[k]
                        row = npair + k
                        if w == 0:
                            Jm[row, 3 * i] = 1.0
                        elif w == 1:
                            Jm[row, 3 * i] = -1.0
                        elif w == 2:
                            Jm[row, 3 * i + 1] = 1.0
                        else:
                            Jm[row, 3 * i + 1] = -1.0
                        Jm[row, 3 * i + 2] = -1.0
                    return Jm

                z_init = out.reshape(-1).copy()
                res = least_squares(
                    F, z_init, jac=J, method='lm',
                    ftol=1e-15, xtol=1e-15, gtol=1e-15, max_nfev=200,
                )
                if res.success and res.x is not None:
                    cand = res.x.reshape(n, 3).copy()
                    cand[:, 2] = np.maximum(cand[:, 2], 1e-11)
                    xc2 = cand[:, 0].copy()
                    yc2 = cand[:, 1].copy()
                    rc2 = cand[:, 2].copy()
                    r2 = final_shrink(xc2, yc2, rc2)
                    if float(np.sum(r2)) > float(np.sum(out[:, 2])):
                        out = np.column_stack([xc2, yc2, r2])
        except Exception:
            pass

    return out
